  ('s1', 2, 'Au kommt vom lateinischen „aurum“. Ag steht für Silber (argentum).', '{"en":{"explanation":"Au comes from the Latin “aurum”. Ag stands for silver (argentum)."}}'::jsonb),
  ('s2', 1, 'Bei rund 150 Millionen Kilometern Abstand braucht Licht etwa 8 Minuten und 20 Sekunden.', '{"en":{"explanation":"At a distance of about 150 million kilometres, light takes roughly 8 minutes and 20 seconds."}}'::jsonb),
