  ('ef2', 0, 'Im Königreich Lydien in der heutigen Türkei entstanden im 7. Jahrhundert v. Chr. die ersten Münzen.', '{"en":{"explanation":"The first coins were made in the 7th century BC in the kingdom of Lydia, in what is now Turkey."}}'::jsonb),
  ('em3', 1, 'Höhere Renditechancen gehen grundsätzlich mit höherem Risiko einher. Wer beides ohne Haken verspricht, ist oft ein Betrüger.', '{"en":{"explanation":"Higher potential returns generally come with higher risk. Anyone promising both with no catch is often a fraudster."}}'::jsonb),
  ('cm2', 1, 'Frankenstein ist der Name des Wissenschaftlers Victor Frankenstein. Sein Geschöpf bleibt im Roman namenlos.', '{"en":{"explanation":"Frankenstein is the name of the scientist, Victor Frankenstein. His creature remains nameless in the novel."}}'::jsonb),
  ('cf2', 0, 'Sie wurden dort über mehr als tausend Jahre zu Ehren des Gottes Zeus ausgetragen.', '{"en":{"explanation":"They were held there for more than a thousand years in honour of the god Zeus."}}'::jsonb),
  ('cm3', 1, 'Die Melodie stammt von Franz Xaver Gruber, der Text von Joseph Mohr. Uraufgeführt wurde es 1818 bei Salzburg.', '{"en":{"explanation":"The melody is by Franz Xaver Gruber and the words by Joseph Mohr. It was first performed near Salzburg in 1818."}}'::jsonb),
  ('q-v-iss-nacht', 0, 'Etwa 90 Minuten – die Besatzung erlebt deshalb rund 16 Sonnenaufgänge am Tag.', '{"en":{"explanation":"About 90 minutes – so the crew sees around 16 sunrises a day."}}'::jsonb),
  ('q-v-saturn-v', 0, 'Die dreistufige Saturn V startete zwischen 1967 und 1973 insgesamt 13 Mal.', '{"en":{"explanation":"The three-stage Saturn V launched 13 times between 1967 and 1973."}}'::jsonb),
  ('q-v-aldrin', 0, 'Michael Collins blieb währenddessen im Kommandomodul in der Mondumlaufbahn.', '{"en":{"explanation":"Meanwhile, Michael Collins stayed in the command module in lunar orbit."}}'::jsonb),
  ('q-v-ingenuity', 0, 'Ingenuity reiste zusammen mit dem Rover Perseverance zum Mars.', '{"en":{"explanation":"Ingenuity travelled to Mars together with the rover Perseverance."}}'::jsonb),
  ('q-v-sonne', 0, 'Im Kern verschmilzt Wasserstoff zu Helium – daher stammt die Energie der Sonne.', '{"en":{"explanation":"In the core, hydrogen fuses into helium – that is where the Sun''s energy comes from."}}'::jsonb),
  ('q-v-hurrikan', 0, 'Um das Auge liegt die Augenwand mit den höchsten Windgeschwindigkeiten.', '{"en":{"explanation":"Around the eye lies the eyewall, with the highest wind speeds."}}'::jsonb),
  ('b1', 1, 'Start-ups probieren ein neues Geschäftsmodell aus und wollen schnell wachsen.', '{"en":{"explanation":"Start-ups try out a new business model and aim to grow quickly."}}'::jsonb),
  ('b2', 0, 'Der CEO leitet das Unternehmen – im Deutschen meist Vorstandsvorsitzender oder Geschäftsführer.', '{"en":{"explanation":"The CEO heads the company."}}'::jsonb),
  ('b3', 2, 'Umsatz ist, was hereinkommt – noch bevor Kosten abgezogen werden.', '{"en":{"explanation":"Revenue is what comes in – before any costs are deducted."}}'::jsonb),
  ('b4', 1, 'Sind die Kosten höher als der Umsatz, entsteht ein Verlust.', '{"en":{"explanation":"If costs are higher than revenue, the result is a loss."}}'::jsonb),
  ('b5', 0, 'B2B steht für „Business to Business“. Verkauft ein Unternehmen an Privatkunden, heißt das B2C.', '{"en":{"explanation":"B2B stands for “business to business”. Selling to private customers is called B2C."}}'::jsonb),
  ('b6', 2, 'Es beantwortet: Für wen schaffen wir welchen Wert – und wer bezahlt dafür?', '{"en":{"explanation":"It answers: for whom do we create which value – and who pays for it?"}}'::jsonb),
  ('b7', 1, 'Ab diesem Punkt macht ein Unternehmen oder Produkt Gewinn.', '{"en":{"explanation":"From this point on, a company or product makes a profit."}}'::jsonb),
  ('b8', 2, 'Wozniak entwickelte die ersten Apple-Computer. Dritter Mitgründer war Ronald Wayne, der früh ausstieg.', '{"en":{"explanation":"Wozniak designed the first Apple computers. The third co-founder, Ronald Wayne, left early on."}}'::jsonb),
  ('b9', 1, 'Jeff Bezos gründete Amazon 1994; 1995 ging der Buchshop online.', '{"en":{"explanation":"Jeff Bezos founded Amazon in 1994; the bookshop went online in 1995."}}'::jsonb),
  ('b10', 1, 'Die Investoren tragen ein hohes Risiko und hoffen, dass der Wert ihrer Anteile stark steigt.', '{"en":{"explanation":"The investors take a high risk and hope that the value of their shares rises sharply."}}'::jsonb),
  ('b11', 2, 'Software skaliert gut: Eine weitere Kopie kostet fast nichts.', '{"en":{"explanation":"Software scales well: one more copy costs almost nothing."}}'::jsonb),
  ('b12', 1, 'Starke Marken schaffen Vertrauen – und erlauben oft höhere Preise.', '{"en":{"explanation":"Strong brands create trust – and often allow higher prices."}}'::jsonb),
  ('b13', 0, 'Die Bauzeit eines Model T sank damit von über zwölf Stunden auf rund anderthalb.', '{"en":{"explanation":"It cut the time to build a Model T from more than twelve hours to about an hour and a half."}}'::jsonb),
  ('b14', 1, 'Viele Restaurant- und Hotelketten wachsen über Franchise-Partner.', '{"en":{"explanation":"Many restaurant and hotel chains grow through franchise partners."}}'::jsonb),
  ('b15', 2, 'Dazu gehören Produkt, Preis, Vertrieb und Werbung.', '{"en":{"explanation":"It includes product, price, distribution and advertising."}}'::jsonb),
  ('b16', 0, 'Die Gesellschafter haften in der Regel nur mit dem Vermögen der Gesellschaft, nicht mit ihrem privaten.', '{"en":{"explanation":"As a rule, the owners are liable only with the company''s assets, not with their private ones."}}'::jsonb),
  ('b17', 0, 'Mit dem Börsengang beschafft sich ein Unternehmen Geld von vielen Anlegern.', '{"en":{"explanation":"With an IPO, a company raises money from many investors."}}'::jsonb),
  ('bf1', 0, 'Das Unternehmen wurde 1865 in Finnland als Holzschliff- und Papierfabrik gegründet – lange vor den Mobiltelefonen.', '{"en":{"explanation":"The company was founded in Finland in 1865 as a wood pulp and paper mill – long before mobile phones."}}'::jsonb),
  ('bf2', 0, 'Fast hundert Jahre lang stellte Nintendo vor allem Spielkarten her, bevor Videospiele das Geschäft bestimmten.', '{"en":{"explanation":"For almost a hundred years Nintendo mainly made playing cards before video games came to dominate its business."}}'::jsonb),
  ('bm1', 1, 'Die große Mehrheit der Start-ups scheitert oder bleibt klein. Investoren rechnen damit, dass wenige Erfolge viele Ausfälle ausgleichen.', '{"en":{"explanation":"The great majority of start-ups fail or stay small. Investors expect a few successes to make up for many failures."}}'::jsonb),
  ('bm2', 1, 'Umsatz sind alle Einnahmen. Gewinn ist, was nach Abzug aller Kosten davon übrig bleibt.', '{"en":{"explanation":"Revenue is all the money coming in. Profit is what remains of it after all costs are deducted."}}'::jsonb),
  ('q-v-blitz', 1, 'Der Blitzkanal erhitzt die Luft so schnell, dass eine Druckwelle entsteht.', '{"en":{"explanation":"The lightning channel heats the air so quickly that a shock wave forms."}}'::jsonb),
  ('q-v-polarlicht', 1, 'Das Magnetfeld der Erde lenkt die Teilchen zu den Polen – deshalb sieht man Polarlichter vor allem dort.', '{"en":{"explanation":"Earth''s magnetic field guides the particles towards the poles – which is why auroras are mainly seen there."}}'::jsonb),
  ('q-v-keimung', 0, 'Die meisten Samen keimen auch im Dunkeln – zum Beispiel in der Erde.', '{"en":{"explanation":"Most seeds germinate even in the dark – in the soil, for example."}}'::jsonb),
  ('q-v-tacoma', 1, 'Der gleichmäßige Wind schaukelte die schlanke Fahrbahn immer weiter auf.', '{"en":{"explanation":"The steady wind kept amplifying the movement of the slender deck."}}'::jsonb),
  ('q-v-3d-druck', 2, 'Deshalb heißt das Verfahren auch additive Fertigung: Es wird Material hinzugefügt, nicht abgetragen.', '{"en":{"explanation":"That is why the process is also called additive manufacturing: material is added, not removed."}}'::jsonb),
  ('q-v-mars-landung', 1, 'Jezero war vor Milliarden Jahren ein See – ein guter Ort, um nach Spuren früheren Lebens zu suchen.', '{"en":{"explanation":"Billions of years ago Jezero was a lake – a good place to look for traces of past life."}}'::jsonb),
  ('q-v-erdaufgang', 2, 'Frank Borman, Jim Lovell und William Anders umrundeten den Mond zehnmal.', '{"en":{"explanation":"Frank Borman, Jim Lovell and William Anders circled the Moon ten times."}}'::jsonb),
  ('q-v-titanic', 1, 'Sie sank in der Nacht vom 14. auf den 15. April 1912 im Nordatlantik.', '{"en":{"explanation":"She sank in the North Atlantic on the night of 14 to 15 April 1912."}}'::jsonb),
  ('q-v-flugpioniere', 0, 'Orville Wright flog am 17. Dezember 1903 rund 37 Meter weit.', '{"en":{"explanation":"On 17 December 1903 Orville Wright flew about 37 metres."}}'::jsonb),
  ('q-v-buchdruck', 1, 'Aus einzelnen Lettern ließ sich jede Seite neu zusammensetzen – und danach wiederverwenden.', '{"en":{"explanation":"Any page could be composed from individual letters – and the letters reused afterwards."}}'::jsonb),
  ('q-v-lumiere', 1, 'Auguste und Louis Lumière führten ihren „Cinématographe“ am 28. Dezember 1895 vor.', '{"en":{"explanation":"Auguste and Louis Lumière presented their “Cinématographe” on 28 December 1895."}}'::jsonb),
  ('q-v-roundhay', 1, 'Louis Le Prince drehte ihn sieben Jahre vor den ersten Kinovorführungen der Brüder Lumière.', '{"en":{"explanation":"Louis Le Prince shot it seven years before the Lumière brothers'' first cinema screenings."}}'::jsonb),
  ('q-v-reise-zum-mond', 2, 'Méliès drehte mehr als 500 Filme und gilt als Pionier der Filmtricks.', '{"en":{"explanation":"Méliès made more than 500 films and is regarded as a pioneer of special effects."}}'::jsonb),
  ('q-v-orchester', 3, 'Geigen, Bratschen, Celli und Kontrabässe stellen meist mehr als die Hälfte der Musiker.', '{"en":{"explanation":"Violins, violas, cellos and double basses usually make up more than half of the players."}}'::jsonb),
  ('q-v-vulkan', 1, 'Tritt Magma an der Oberfläche aus, heißt es Lava.', '{"en":{"explanation":"When magma emerges at the surface, it is called lava."}}'::jsonb),
  ('q-v-gepard', 0, 'Wie ein Ruder gleicht der Schwanz schnelle Richtungswechsel aus.', '{"en":{"explanation":"Like a rudder, the tail compensates for rapid changes of direction."}}'::jsonb),
  ('q-v-oktopus', 2, 'Der kupferhaltige Blutfarbstoff Hämocyanin färbt es blau.', '{"en":{"explanation":"The copper-containing blood pigment haemocyanin makes it blue."}}'::jsonb),
  ('q-v-bienen', 1, 'Der Tanz verrät Richtung und Entfernung einer Futterquelle.', '{"en":{"explanation":"The dance reveals the direction and distance of a food source."}}'::jsonb),
  ('q-v-stare', 1, 'Im Gewimmel kann sich ein Angreifer kaum auf ein einzelnes Tier konzentrieren.', '{"en":{"explanation":"In the swirl, an attacker can hardly focus on a single animal."}}'::jsonb),
  ('q-v-banknoten', 2, 'Einige Länder wie Australien oder Großbritannien nutzen dagegen Kunststoff.', '{"en":{"explanation":"Some countries, such as Australia and the United Kingdom, use plastic instead."}}'::jsonb),
  ('q-v-muenzen', 1, 'Der Ort, an dem Münzen geprägt werden, heißt Münzprägeanstalt oder kurz Münze.', '{"en":{"explanation":"The place where coins are made is called a mint."}}'::jsonb),
  ('q-v-container', 0, 'Früher wurde jede Kiste und jeder Sack einzeln verladen.', '{"en":{"explanation":"In the past every crate and sack was loaded individually."}}'::jsonb),
  ('q-v-fliessband', 0, 'Massenproduktion senkt die Kosten pro Stück – ein Grundprinzip vieler Geschäftsmodelle.', '{"en":{"explanation":"Mass production lowers the cost per unit – a basic principle of many business models."}}'::jsonb),
  ('q-v-supermarkt', 1, 'Vorher reichte ein Verkäufer jede Ware über die Theke.', '{"en":{"explanation":"Before that, a shop assistant handed every item over the counter."}}'::jsonb),
  ('q-v-buero', 1, 'Die Anordnung QWERTY entstand in den 1870er-Jahren.', '{"en":{"explanation":"The QWERTY layout dates from the 1870s."}}'::jsonb),
  ('qa-herz', 2, 'Die linke Kammer hat die dickste Muskelwand, weil sie das Blut durch den ganzen Körper drücken muss. Die rechte Kammer pumpt nur zur Lunge.', '{"en":{"explanation":"The left ventricle has the thickest muscle wall because it has to push blood through the whole body. The right ventricle only pumps to the lungs."}}'::jsonb),
  ('qa-motor', 2, 'Nur im Arbeitstakt drückt das brennende Gas den Kolben nach unten. Die anderen drei Takte verbrauchen einen Teil dieser Energie.', '{"en":{"explanation":"Only in the power stroke does the burning gas push the piston down. The other three strokes use up part of that energy."}}'::jsonb),
  ('qa-gewitter', 0, 'Der schwere, negativ geladene Graupel sammelt sich unten, die leichten, positiv geladenen Eiskristalle oben. Zwischen Wolke und Boden entsteht so eine hohe Spannung.', '{"en":{"explanation":"The heavy, negatively charged graupel collects at the bottom, the light, positively charged ice crystals at the top. This creates a high voltage between cloud and ground."}}'::jsonb),
  ('qa-batterie', 1, 'Durch den Draht fließen Elektronen vom Minuspol zum Pluspol. Im Inneren der Batterie wandern dagegen Ionen durch den Elektrolyten.', '{"en":{"explanation":"Electrons flow through the wire from the negative to the positive terminal. Inside the battery, by contrast, ions move through the electrolyte."}}'::jsonb),
  ('qa-platten', 1, 'Das aufsteigende Magma erstarrt zu neuer Kruste – so wächst zum Beispiel der Atlantik jedes Jahr um einige Zentimeter.', '{"en":{"explanation":"The rising magma solidifies into new crust – this is how the Atlantic, for example, widens by a few centimetres every year."}}'::jsonb),
  ('m1', 3, 'Primzahlen haben genau zwei Teiler. Die kleinste ist 2 – die einzige gerade Primzahl.', '{"en":{"explanation":"Prime numbers have exactly two divisors. The smallest is 2 – the only even prime."}}'::jsonb),
  ('m2', 0, 'Egal wie das Dreieck aussieht: Die drei Innenwinkel ergeben zusammen immer 180 Grad.', '{"en":{"explanation":"Whatever the triangle looks like, its three interior angles always add up to 180 degrees."}}'::jsonb),
  ('m3', 1, 'Pi ist das Verhältnis von Umfang zu Durchmesser eines Kreises – bei jedem Kreis gleich.', '{"en":{"explanation":"Pi is the ratio of a circle''s circumference to its diameter – the same for every circle."}}'::jsonb),
  ('m4', 2, 'Die Quadrate über den beiden kurzen Seiten sind zusammen so groß wie das Quadrat über der längsten Seite.', '{"en":{"explanation":"The squares on the two shorter sides together equal the square on the longest side."}}'::jsonb),
  ('m5', 3, '10 Prozent von 200 sind 20, 5 Prozent sind 10 – zusammen 30.', '{"en":{"explanation":"10 percent of 200 is 20, 5 percent is 10 – together 30."}}'::jsonb),
  ('m6', 0, '12 mal 12 ergibt 144.', '{"en":{"explanation":"12 times 12 is 144."}}'::jsonb),
  ('m7', 1, 'Der Median teilt die sortierte Reihe in zwei Hälften. Anders als der Durchschnitt wird er von einzelnen Ausreißern kaum verzerrt.', '{"en":{"explanation":"The median splits the sorted series into two halves. Unlike the average, it is hardly distorted by single outliers."}}'::jsonb),
  ('m8', 2, 'Ein Hexagon ist ein Sechseck – wie die Zellen einer Bienenwabe.', '{"en":{"explanation":"A hexagon has six sides – like the cells of a honeycomb."}}'::jsonb),
  ('m9', 3, 'Zehnmal verdoppelt: 2, 4, 8, 16, 32, 64, 128, 256, 512, 1024.', '{"en":{"explanation":"Doubled ten times: 2, 4, 8, 16, 32, 64, 128, 256, 512, 1024."}}'::jsonb),
  ('m10', 1, 'Der Würfel hat sechs gleich wahrscheinliche Seiten, eine davon ist die Sechs.', '{"en":{"explanation":"The die has six equally likely faces, one of which is the six."}}'::jsonb),
  ('m11', 2, 'Jede Zahl ist die Summe der beiden vorherigen: 5 + 8 = 13.', '{"en":{"explanation":"Each number is the sum of the two before it: 5 + 8 = 13."}}'::jsonb),
  ('m12', 3, 'Spitze Winkel sind kleiner als 90 Grad, stumpfe größer; ein gestreckter Winkel hat 180 Grad.', '{"en":{"explanation":"Acute angles are smaller than 90 degrees, obtuse ones larger; a straight angle is 180 degrees."}}'::jsonb),
  ('m13', 0, 'Ein Rechteck mit 4 m Länge und 3 m Breite hat 12 Quadratmeter Fläche.', '{"en":{"explanation":"A rectangle 4 m long and 3 m wide has an area of 12 square metres."}}'::jsonb),
  ('m14', 1, 'I = 1, V = 5, X = 10, L = 50, C = 100, D = 500, M = 1000.', '{"en":{"explanation":"I = 1, V = 5, X = 10, L = 50, C = 100, D = 500, M = 1000."}}'::jsonb),
  ('m15', 2, '1.000.000 – eine Million sind tausend mal tausend.', '{"en":{"explanation":"1,000,000 – a million is a thousand times a thousand."}}'::jsonb),
  ('m16', 3, 'Zusammen ergeben die Zahlen 24. Geteilt durch drei Zahlen: 8.', '{"en":{"explanation":"Together the numbers add up to 24. Divided by three numbers: 8."}}'::jsonb),
  ('m17', 0, 'Ein Viertel ist die Hälfte von einer Hälfte: 0,5 geteilt durch 2.', '{"en":{"explanation":"A quarter is half of a half: 0.5 divided by 2."}}'::jsonb),
  ('m18', 1, 'Die Einteilung in 360 Grad geht auf die Babylonier zurück.', '{"en":{"explanation":"The division into 360 degrees goes back to the Babylonians."}}'::jsonb),
  ('m19', 3, 'Die schnell welkenden Blumen könnten alle andere Blumen sein. Über Rosen sagen die beiden Sätze dazu nichts.', '{"en":{"explanation":"The quickly wilting flowers could all be other flowers. The two statements say nothing about roses in this respect."}}'::jsonb),
  ('m20', 0, 'Beispiel: 3 + x = 7. Die Gleichung stimmt, wenn x den Wert 4 hat.', '{"en":{"explanation":"Example: 3 + x = 7. The equation is true when x equals 4."}}'::jsonb),
  ('m21', 1, 'Ein Würfel hat 8 Ecken, 12 Kanten und 6 Flächen.', '{"en":{"explanation":"A cube has 8 corners, 12 edges and 6 faces."}}'::jsonb),
  ('m22', 2, 'Jede Zahl ist das Doppelte der vorherigen.', '{"en":{"explanation":"Each number is double the one before."}}'::jsonb),
  ('m23', 3, 'x ≥ 5 heißt: x ist 5 oder eine größere Zahl.', '{"en":{"explanation":"x ≥ 5 means: x is 5 or a larger number."}}'::jsonb),
  ('m24', 0, '25 Prozent von 40 Euro sind 10 Euro. 40 − 10 = 30.', '{"en":{"explanation":"25 percent of 40 euros is 10 euros. 40 − 10 = 30."}}'::jsonb),
  ('m25', 1, 'Sein Beweis steht in den „Elementen“, einem der einflussreichsten Mathematikbücher der Geschichte.', '{"en":{"explanation":"His proof is in the “Elements”, one of the most influential mathematics books in history."}}'::jsonb),
  ('l1', 0, 'Adjektive beschreiben, wie etwas ist. Hier beschreibt „schnelle“ den Hund.', '{"en":{"explanation":"Adjectives describe what something is like. Here “schnelle” (fast) describes the dog."}}'::jsonb),
  ('l2', 1, 'Nominativ, Genitiv, Dativ und Akkusativ.', '{"en":{"explanation":"Nominative, genitive, dative and accusative."}}'::jsonb),
  ('l3', 2, '„Anfangen“ und „beginnen“ sind Synonyme.', '{"en":{"explanation":"“Start” and “begin” are synonyms."}}'::jsonb),
  ('l4', 3, '„Heiß“ und „kalt“ sind Antonyme.', '{"en":{"explanation":"“Hot” and “cold” are antonyms."}}'::jsonb),
  ('l5', 0, 'Beispiele sind „Anna“, „Otto“ oder „Rentner“.', '{"en":{"explanation":"Examples are “level”, “radar” or “Anna”."}}'::jsonb),
  ('l6', 1, 'Das Perfekt wird mit „haben“ oder „sein“ und dem Partizip gebildet. Im Gesprochenen ist es die übliche Vergangenheitsform.', '{"en":{"explanation":"The German perfect is formed with “haben” or “sein” and the participle. It is the usual past tense in spoken German."}}'::jsonb),
  ('l7', 2, 'Ein „falscher Freund“: Es klingt nach dem französischen „librairie“ (Buchhandlung), meint aber die Bibliothek. Buchhandlung heißt „bookshop“.', '{"en":{"explanation":"A “false friend”: it sounds like the French “librairie” (bookshop) but means “Bibliothek”. A bookshop is a “Buchhandlung”."}}'::jsonb),
  ('l8', 3, 'Ein typischer falscher Freund. „Bekommen“ heißt auf Englisch „to get“ oder „to receive“.', '{"en":{"explanation":"A typical false friend. The German “bekommen” means “to get” or “to receive”."}}'::jsonb),
  ('l9', 0, 'Es sind die 26 Buchstaben des lateinischen Alphabets. Dazu kommen ä, ö, ü und ß.', '{"en":{"explanation":"They are the 26 letters of the Latin alphabet. German adds ä, ö, ü and ß."}}'::jsonb),
  ('l10', 0, '„Das Herz der Stadt“ meint kein Organ, sondern das Zentrum.', '{"en":{"explanation":"“The heart of the city” does not mean an organ but the centre."}}'::jsonb),
  ('l11', 1, 'Friedrich Fröbel prägte den Begriff 1840. Auch „Rucksack“ und „Zeitgeist“ sind ins Englische gewandert.', '{"en":{"explanation":"Friedrich Fröbel coined the term in 1840. “Rucksack” and “zeitgeist” also made their way into English."}}'::jsonb),
  ('l12', 2, '„NASA“ oder „UNO“ sind Akronyme: Man spricht die Anfangsbuchstaben wie ein Wort.', '{"en":{"explanation":"“NASA” and “UNESCO” are acronyms: the initial letters are spoken as one word."}}'::jsonb),
  ('l13', 3, 'Auch Schwedisch, Dänisch und Norwegisch sind germanische Sprachen.', '{"en":{"explanation":"Swedish, Danish and Norwegian are Germanic languages too."}}'::jsonb),
  ('l14', 0, 'Sie heißen romanische Sprachen, weil sie aus dem Latein der Römer entstanden sind.', '{"en":{"explanation":"They are called Romance languages because they grew out of the Latin of the Romans."}}'::jsonb),
  ('l15', 1, 'Der Konjunktiv drückt aus, was nur gewünscht, gedacht oder möglich ist.', '{"en":{"explanation":"The subjunctive (Konjunktiv) expresses what is only wished for, imagined or possible."}}'::jsonb),
  ('l16', 0, 'Das Subjekt ist, wer oder was etwas tut. Man fragt: Wer oder was jagt?', '{"en":{"explanation":"The subject is who or what does something. Ask: who or what is chasing?"}}'::jsonb),
  ('l17', 3, 'Kyrillisch wird auch für Ukrainisch, Bulgarisch und Serbisch verwendet.', '{"en":{"explanation":"Cyrillic is also used for Ukrainian, Bulgarian and Serbian."}}'::jsonb),
  ('l18', 0, 'Die meisten davon haben nur wenige Sprecher; viele gelten als bedroht.', '{"en":{"explanation":"Most of them have only a few speakers; many are considered endangered."}}'::jsonb),
  ('l19', 1, '„Milch macht müde Männer munter“ ist ein bekanntes Beispiel.', '{"en":{"explanation":"“Peter Piper picked a peck of pickled peppers” is a well-known example."}}'::jsonb),
  ('l20', 3, 'Die Wendung stammt vermutlich aus der Sprache der Schützen: Der Nagel markierte die Mitte der Zielscheibe.', '{"en":{"explanation":"The phrase probably comes from marksmen''s language: the nail marked the centre of the target."}}'::jsonb),
  ('l21', 0, '„Dass“ leitet einen Nebensatz ein. Lässt sich das Wort durch „dieses“ oder „welches“ ersetzen, schreibt man „das“.', '{"en":{"explanation":"“Dass” (that) introduces a subordinate clause. If the word can be replaced by “dieses” or “welches”, it is spelled “das”."}}'::jsonb),
  ('l22', 1, 'Sie wird mit „to be“ und der „-ing“-Form gebildet und heißt auch „Present Continuous“.', '{"en":{"explanation":"It is formed with “to be” and the “-ing” form and is also called the present continuous."}}'::jsonb),
  ('s21', 3, 'Die Haut eines Erwachsenen hat eine Fläche von etwa 1,5 bis 2 Quadratmetern.', '{"en":{"explanation":"An adult''s skin has an area of about 1.5 to 2 square metres."}}'::jsonb),
  ('s22', 0, 'Sie enthalten den roten Farbstoff Hämoglobin, der den Sauerstoff bindet.', '{"en":{"explanation":"They contain the red pigment haemoglobin, which binds the oxygen."}}'::jsonb),
  ('s23', 1, 'Es sind 23 Paare – jeweils ein Chromosom von der Mutter und eines vom Vater.', '{"en":{"explanation":"There are 23 pairs – one chromosome each from the mother and the father."}}'::jsonb),
  ('s24', 2, 'Das Immunsystem lernt den Erreger kennen, ohne dass man die Krankheit durchmachen muss, und reagiert später schneller.', '{"en":{"explanation":"The immune system gets to know the pathogen without the person having to go through the disease, and reacts faster later on."}}'::jsonb),
  ('s25', 3, 'Gegen Viren – etwa bei einer Erkältung oder Grippe – helfen Antibiotika nicht.', '{"en":{"explanation":"Antibiotics do not help against viruses – for example with a cold or the flu."}}'::jsonb),
  ('s26', 0, 'pH 7 gilt als neutral. Werte darunter sind sauer, Werte darüber basisch.', '{"en":{"explanation":"pH 7 is considered neutral. Values below are acidic, values above are basic (alkaline)."}}'::jsonb),
  ('s27', 1, 'Kochsalz ist Natriumchlorid, chemische Formel NaCl.', '{"en":{"explanation":"Table salt is sodium chloride, chemical formula NaCl."}}'::jsonb),
  ('s28', 2, 'Trockeneis – gefrorenes Kohlendioxid – wird ohne zu schmelzen direkt zu Gas.', '{"en":{"explanation":"Dry ice – frozen carbon dioxide – turns straight into gas without melting."}}'::jsonb),
  ('s29', 3, 'Stößt du dich auf einem Skateboard von einer Wand ab, drückt die Wand genauso stark zurück – deshalb rollst du los.', '{"en":{"explanation":"If you push off a wall on a skateboard, the wall pushes back just as hard – that is why you roll away."}}'::jsonb),
  ('s30', 1, 'Ampere misst die Stromstärke, Watt die Leistung und Ohm den Widerstand.', '{"en":{"explanation":"Ampere measures current, watt measures power and ohm measures resistance."}}'::jsonb),
  ('s31', 1, 'Kälter geht es nicht. Auf der Kelvin-Skala ist das der Wert 0.', '{"en":{"explanation":"Nothing can be colder. On the Kelvin scale this is the value 0."}}'::jsonb),
  ('s32', 3, 'Im Regenbogen liegt Rot deshalb außen, Violett mit der kürzesten Wellenlänge innen.', '{"en":{"explanation":"That is why red is on the outside of a rainbow and violet, with the shortest wavelength, on the inside."}}'::jsonb),
  ('s33', 0, 'Die Iris ist der farbige Ring. Sie macht die Pupille in ihrer Mitte je nach Helligkeit enger oder weiter.', '{"en":{"explanation":"The iris is the coloured ring. It makes the pupil in its centre narrower or wider depending on the brightness."}}'::jsonb),
  ('s34', 1, 'Auf Englisch heißt er „confirmation bias“. Wer ihn kennt, sucht bewusst auch nach Gegenargumenten.', '{"en":{"explanation":"Those who know about it deliberately look for counter-arguments as well."}}'::jsonb),
  ('s35', 2, 'Die Hunde speichelten schließlich schon beim Ton einer Glocke. Das nennt man klassische Konditionierung.', '{"en":{"explanation":"In the end the dogs salivated at the mere sound of a bell. This is called classical conditioning."}}'::jsonb),
  ('s36', 3, 'In Studien dient es zum Vergleich: Nur was besser wirkt als das Placebo, gilt als wirksam.', '{"en":{"explanation":"In studies it serves as a comparison: only what works better than the placebo counts as effective."}}'::jsonb),
  ('s37', 0, 'Verbinden sich mehrere Atome, entsteht ein Molekül.', '{"en":{"explanation":"When several atoms bond together, a molecule is formed."}}'::jsonb),
  ('s38', 1, 'Es entsteht, wenn die Zellen mit Sauerstoff Energie aus der Nahrung gewinnen.', '{"en":{"explanation":"It is produced when the cells use oxygen to obtain energy from food."}}'::jsonb),
  ('t21', 0, 'Er leitet Datenpakete zwischen dem Heimnetz und dem Internet weiter und spannt meist auch das WLAN auf.', '{"en":{"explanation":"It forwards data packets between the home network and the internet and usually provides the Wi-Fi as well."}}'::jsonb),
  ('t22', 1, 'Das „s“ steht für „secure“. Ob der Inhalt der Seite stimmt, sagt es allerdings nicht.', '{"en":{"explanation":"The “s” stands for “secure”. It says nothing, however, about whether the site''s content is true."}}'::jsonb),
  ('t23', 2, 'Der zweite Faktor ist zum Beispiel ein Code aus einer App. Ein gestohlenes Passwort allein reicht dann nicht.', '{"en":{"explanation":"The second factor is, for example, a code from an app. A stolen password alone is then not enough."}}'::jsonb),
  ('t24', 3, 'Sie funktioniert wie eine Postanschrift: Datenpakete finden damit ihr Ziel.', '{"en":{"explanation":"It works like a postal address: data packets use it to find their destination."}}'::jsonb),
  ('t25', 0, 'Beispiele sind Windows, macOS, Linux, Android und iOS.', '{"en":{"explanation":"Examples are Windows, macOS, Linux, Android and iOS."}}'::jsonb),
  ('t26', 1, 'Die Vorsilben folgen dem Tausenderschritt: Kilo, Mega, Giga, Tera.', '{"en":{"explanation":"The prefixes go up in steps of a thousand: kilo, mega, giga, tera."}}'::jsonb),
  ('t27', 2, 'Beim Training werden die Verbindungen zwischen den Einheiten so angepasst, dass die Ergebnisse besser werden.', '{"en":{"explanation":"During training, the connections between the units are adjusted so that the results improve."}}'::jsonb),
  ('t28', 3, 'Sprachmodelle berechnen wahrscheinliche Wortfolgen. Deshalb sollte man wichtige Angaben immer nachprüfen.', '{"en":{"explanation":"Language models compute likely sequences of words. That is why important information should always be checked."}}'::jsonb),
  ('t29', 0, 'Trifft Licht auf die Zelle, setzt es im Halbleiter Elektronen in Bewegung.', '{"en":{"explanation":"When light hits the cell, it sets electrons in motion in the semiconductor."}}'::jsonb),
  ('t30', 2, 'Stromdurchflossene Spulen und Magnete stoßen sich ab und ziehen sich an – daraus entsteht die Drehung.', '{"en":{"explanation":"Current-carrying coils and magnets repel and attract each other – this produces the rotation."}}'::jsonb),
  ('t31', 3, 'Aus den Laufzeiten der Signale mehrerer Satelliten berechnet das Gerät seine Position.', '{"en":{"explanation":"The device calculates its position from the travel times of the signals of several satellites."}}'::jsonb),
  ('t32', 0, 'Unter dem Namen kann das Programm den Wert später wieder lesen oder ändern.', '{"en":{"explanation":"Under that name the program can read or change the value again later."}}'::jsonb),
  ('t33', 1, 'Deepfakes können Menschen Dinge sagen oder tun lassen, die nie passiert sind. Im Zweifel hilft der Blick auf die Quelle.', '{"en":{"explanation":"Deepfakes can make people appear to say or do things that never happened. When in doubt, check the source."}}'::jsonb),
  ('t34', 2, 'Je klarer die Eingabe Ziel, Kontext und gewünschtes Format beschreibt, desto brauchbarer ist meist das Ergebnis.', '{"en":{"explanation":"The more clearly the input describes the goal, context and desired format, the more useful the result usually is."}}'::jsonb),
  ('h21', 0, 'Angela Merkel blieb 16 Jahre im Amt, bis 2021.', '{"en":{"explanation":"Angela Merkel remained in office for 16 years, until 2021."}}'::jsonb),
  ('h22', 1, 'Am 3. Oktober 1990 trat die DDR der Bundesrepublik bei. Die Mauer war schon 1989 gefallen.', '{"en":{"explanation":"On 3 October 1990 East Germany joined the Federal Republic. The Wall had already fallen in 1989."}}'::jsonb),
  ('h23', 2, 'Im 5. Jahrhundert v. Chr. stimmten dort die Bürger selbst über Gesetze ab – Frauen, Sklaven und Zugezogene waren allerdings ausgeschlossen.', '{"en":{"explanation":"In the 5th century BC its citizens voted on laws themselves – although women, slaves and foreigners were excluded."}}'::jsonb),
  ('h24', 3, 'Mandela hatte zuvor 27 Jahre in Haft verbracht, weil er gegen die Rassentrennung gekämpft hatte.', '{"en":{"explanation":"Mandela had previously spent 27 years in prison for fighting against racial segregation."}}'::jsonb),
  ('h25', 0, 'Die Pandemie von 1346 bis 1353 wird auch „Schwarzer Tod“ genannt.', '{"en":{"explanation":"The pandemic of 1346 to 1353 is also called the “Black Death”."}}'::jsonb),
  ('h26', 1, 'James Watt verbesserte sie ab den 1760er-Jahren so, dass sie Fabriken, später auch Lokomotiven und Schiffe antreiben konnte.', '{"en":{"explanation":"From the 1760s James Watt improved it so that it could power factories and later locomotives and ships."}}'::jsonb),
  ('h27', 2, 'Washington war von 1789 bis 1797 im Amt.', '{"en":{"explanation":"Washington was in office from 1789 to 1797."}}'::jsonb),
  ('h28', 3, 'Die Erklärung wurde am 4. Juli 1776 angenommen – bis heute der Nationalfeiertag der USA.', '{"en":{"explanation":"The declaration was adopted on 4 July 1776 – still the national holiday of the USA."}}'::jsonb),
  ('h29', 0, 'Neben Seide wanderten darauf auch Gewürze, Papier, Ideen und Religionen.', '{"en":{"explanation":"Besides silk, spices, paper, ideas and religions also travelled along it."}}'::jsonb),
  ('h30', 2, 'Es wurde zum größten zusammenhängenden Landreich der Geschichte.', '{"en":{"explanation":"It became the largest contiguous land empire in history."}}'::jsonb),
  ('h31', 3, 'Der sowjetische Kosmonaut umrundete am 12. April 1961 einmal die Erde.', '{"en":{"explanation":"The Soviet cosmonaut orbited the Earth once on 12 April 1961."}}'::jsonb),
  ('h32', 0, 'Sie endete mit der Machtübernahme der Nationalsozialisten 1933.', '{"en":{"explanation":"It ended when the National Socialists took power in 1933."}}'::jsonb),
  ('h33', 1, 'Es sind bis heute die einzigen Einsätze von Atomwaffen in einem Krieg.', '{"en":{"explanation":"To this day they are the only uses of nuclear weapons in a war."}}'::jsonb),
  ('h34', 2, 'Er prägte die Weltpolitik von etwa 1947 bis 1989/91 – mit Wettrüsten, Stellvertreterkriegen und dem geteilten Deutschland.', '{"en":{"explanation":"It shaped world politics from about 1947 to 1989/91 – with an arms race, proxy wars and a divided Germany."}}'::jsonb),
  ('h35', 3, 'Fleming bemerkte, dass ein Schimmelpilz in einer Laborschale Bakterien abtötete. Daraus entstand das erste Antibiotikum.', '{"en":{"explanation":"Fleming noticed that a mould in a laboratory dish killed bacteria. This led to the first antibiotic."}}'::jsonb),
  ('g17', 2, 'Die Wolga ist rund 3.500 Kilometer lang und mündet ins Kaspische Meer.', '{"en":{"explanation":"The Volga is about 3,500 kilometres long and flows into the Caspian Sea."}}'::jsonb),
  ('g18', 3, 'Toronto ist die größte Stadt des Landes, Hauptstadt ist aber Ottawa.', '{"en":{"explanation":"Toronto is the country''s largest city, but the capital is Ottawa."}}'::jsonb),
  ('g19', 0, 'Nach Schätzung der Vereinten Nationen hat Indien China 2023 überholt. Beide Länder haben jeweils mehr als 1,4 Milliarden Einwohner.', '{"en":{"explanation":"According to United Nations estimates, India overtook China in 2023. Both countries have more than 1.4 billion inhabitants each."}}'::jsonb),
  ('g20', 2, 'Über die Straße von Gibraltar ist es mit dem Atlantik verbunden.', '{"en":{"explanation":"It is connected to the Atlantic by the Strait of Gibraltar."}}'::jsonb),
  ('g21', 3, 'Es entsteht vor allem beim Verbrennen von Kohle, Öl und Gas.', '{"en":{"explanation":"It is produced mainly by burning coal, oil and gas."}}'::jsonb),
  ('g22', 0, 'Ohne den natürlichen Treibhauseffekt wäre es auf der Erde im Mittel etwa −18 °C kalt. Zusätzliche Treibhausgase verstärken ihn.', '{"en":{"explanation":"Without the natural greenhouse effect, the Earth''s average temperature would be about −18 °C. Additional greenhouse gases strengthen it."}}'::jsonb),
  ('g23', 1, 'Üblicherweise betrachtet man für das Klima einen Zeitraum von 30 Jahren.', '{"en":{"explanation":"For climate, a period of 30 years is usually considered."}}'::jsonb),
  ('g24', 2, 'Sie liegt in etwa 15 bis 30 Kilometern Höhe in der Stratosphäre.', '{"en":{"explanation":"It lies at an altitude of about 15 to 30 kilometres in the stratosphere."}}'::jsonb),
  ('g25', 3, 'Vor allem der Mond zieht das Wasser der Ozeane an. An den meisten Küsten gibt es deshalb zweimal täglich Flut.', '{"en":{"explanation":"The Moon above all pulls on the water of the oceans. Most coasts therefore have high tide twice a day."}}'::jsonb),
  ('g26', 0, 'Dazu gehören Bären, Schweine – und der Mensch.', '{"en":{"explanation":"They include bears, pigs – and humans."}}'::jsonb),
  ('g27', 1, 'Flughörnchen gleiten nur. Fledertiere sind die einzigen Säugetiere, die mit Flügelschlag fliegen.', '{"en":{"explanation":"Flying squirrels only glide. Bats are the only mammals that fly by flapping their wings."}}'::jsonb),
  ('g28', 2, 'Der Großraum Tokio ist mit mehr als 35 Millionen Menschen der bevölkerungsreichste Ballungsraum der Welt.', '{"en":{"explanation":"With more than 35 million people, Greater Tokyo is the most populous metropolitan area in the world."}}'::jsonb),
  ('g29', 3, 'Die Stadt wurde im 15. Jahrhundert in rund 2.400 Metern Höhe in den Anden erbaut.', '{"en":{"explanation":"The city was built in the 15th century at an altitude of about 2,400 metres in the Andes."}}'::jsonb),
  ('g30', 1, 'Vielfältige Ökosysteme sind meist widerstandsfähiger gegen Störungen.', '{"en":{"explanation":"Diverse ecosystems are usually more resilient to disturbances."}}'::jsonb),
  ('g31', 2, 'Der Rhein entspringt in den Schweizer Alpen und mündet in den Niederlanden in die Nordsee.', '{"en":{"explanation":"The Rhine rises in the Swiss Alps and flows into the North Sea in the Netherlands."}}'::jsonb),
  ('e17', 0, 'Die Zinsen sind der Preis dafür, dass man das Geld jetzt schon nutzen kann.', '{"en":{"explanation":"The interest is the price for being able to use the money now."}}'::jsonb),
  ('e18', 1, 'Für viele Lebensmittel und Bücher gilt der ermäßigte Satz von 7 Prozent.', '{"en":{"explanation":"The reduced rate of 7 percent applies to many foods and books."}}'::jsonb),
  ('e19', 2, 'Vom Girokonto gehen Überweisungen, Daueraufträge und Lastschriften ab.', '{"en":{"explanation":"Transfers, standing orders and direct debits are paid from a current account."}}'::jsonb),
  ('e20', 0, 'Wer zwei Stunden fernsieht, „bezahlt“ mit dem, was er in dieser Zeit sonst am liebsten getan hätte.', '{"en":{"explanation":"Someone who watches TV for two hours “pays” with whatever they would most have liked to do in that time."}}'::jsonb),
  ('e21', 1, 'Nicht jedes Unternehmen zahlt Dividenden – manche stecken den Gewinn lieber in ihr Wachstum.', '{"en":{"explanation":"Not every company pays dividends – some prefer to put the profit into their growth."}}'::jsonb),
  ('e22', 2, 'Er entscheidet zum Beispiel, wie viele Dollar man für einen Euro bekommt.', '{"en":{"explanation":"It determines, for example, how many dollars you get for one euro."}}'::jsonb),
  ('e23', 3, 'Das klingt gut, kann aber gefährlich werden: Wer fallende Preise erwartet, verschiebt Käufe – und die Wirtschaft schrumpft.', '{"en":{"explanation":"That sounds good but can be dangerous: people who expect falling prices postpone purchases – and the economy shrinks."}}'::jsonb),
  ('e24', 0, 'Der Käufer erhält Zinsen und am Ende der Laufzeit sein Geld zurück – sofern der Schuldner zahlen kann.', '{"en":{"explanation":"The buyer receives interest and, at the end of the term, their money back – provided the debtor can pay."}}'::jsonb),
  ('e25', 1, 'Die EZB strebt eine Inflationsrate von mittelfristig zwei Prozent an.', '{"en":{"explanation":"The ECB aims for an inflation rate of two percent over the medium term."}}'::jsonb),
  ('e26', 2, 'Als Faustregel werden oft drei Monatsausgaben genannt, die schnell verfügbar sein sollten.', '{"en":{"explanation":"A common rule of thumb is three months'' expenses that should be quickly available."}}'::jsonb),
  ('b18', 2, 'Die Idee: früh lernen, was Kunden wirklich brauchen, statt lange im Verborgenen zu entwickeln.', '{"en":{"explanation":"The idea: learn early what customers really need instead of developing in secret for a long time."}}'::jsonb),
  ('b19', 3, 'Er beschreibt Idee, Markt, Wettbewerb und Finanzen – und ist oft Voraussetzung für Kredite oder Investoren.', '{"en":{"explanation":"It describes the idea, market, competition and finances – and is often required for loans or investors."}}'::jsonb),
  ('b20', 1, 'Miete und Gehälter fallen auch an, wenn nichts verkauft wird. Material dagegen zählt zu den variablen Kosten.', '{"en":{"explanation":"Rent and salaries are due even if nothing is sold. Materials, by contrast, are variable costs."}}'::jsonb),
  ('b21', 2, 'Wer seine Zielgruppe kennt, kann Produkt, Preis und Werbung besser auf sie abstimmen.', '{"en":{"explanation":"Those who know their target group can better tailor product, price and advertising to it."}}'::jsonb),
  ('b22', 3, 'Ein Unternehmen kann auf dem Papier Gewinn machen und trotzdem zahlungsunfähig werden, wenn das Geld zu spät eingeht.', '{"en":{"explanation":"A company can make a profit on paper and still become insolvent if the money comes in too late."}}'::jsonb),
  ('b23', 0, 'In der Regel gilt der Schutz höchstens 20 Jahre. Dafür muss die Erfindung offengelegt werden.', '{"en":{"explanation":"Protection usually lasts no more than 20 years. In return, the invention has to be disclosed."}}'::jsonb),
  ('c18', 3, 'Der Bundestag tagt im Reichstagsgebäude in Berlin – das Gebäude heißt so, das Parlament nicht.', '{"en":{"explanation":"The Bundestag meets in the Reichstag building in Berlin – that is the name of the building, not of the parliament."}}'::jsonb),
  ('c19', 0, 'Eine Wahlperiode dauert vier Jahre, sofern der Bundestag nicht vorzeitig aufgelöst wird.', '{"en":{"explanation":"A legislative period lasts four years unless the Bundestag is dissolved early."}}'::jsonb),
  ('c20', 2, 'Sie legt fest, wie der Staat aufgebaut ist und welche Grundrechte gelten. In Deutschland ist das das Grundgesetz.', '{"en":{"explanation":"It sets out how the state is organised and which fundamental rights apply. In Germany this is the Basic Law (Grundgesetz)."}}'::jsonb),
  ('c21', 3, 'In Deutschland steht sie in Artikel 5 des Grundgesetzes.', '{"en":{"explanation":"In Germany it is laid down in Article 5 of the Basic Law."}}'::jsonb),
  ('c22', 0, 'Viele Likes sagen nichts über den Wahrheitsgehalt. Hilfreich ist die Frage: Wer sagt das – und woher weiß er es?', '{"en":{"explanation":"Lots of likes say nothing about whether something is true. A helpful question: who says so – and how do they know?"}}'::jsonb),
  ('c23', 1, 'Typisch sind Formulierungen wie „Du wirst nicht glauben, was dann geschah“.', '{"en":{"explanation":"Typical phrases are things like “You won''t believe what happened next”."}}'::jsonb),
  ('c24', 2, 'Andere Sichtweisen tauchen dann seltener auf. Wie stark dieser Effekt wirklich ist, wird in der Forschung diskutiert.', '{"en":{"explanation":"Other points of view then appear less often. How strong this effect really is, is debated in research."}}'::jsonb),
  ('c25', 3, 'Das Bild entstand als Reaktion auf die Bombardierung der baskischen Stadt Gernika im Spanischen Bürgerkrieg.', '{"en":{"explanation":"The painting was a response to the bombing of the Basque town of Gernika in the Spanish Civil War."}}'::jsonb),
  ('c26', 0, 'Der erste Band erschien 1997. Die Reihe umfasst sieben Bände.', '{"en":{"explanation":"The first volume was published in 1997. The series comprises seven volumes."}}'::jsonb),
  ('c27', 1, 'Er war außerdem für seine raue Singstimme berühmt, etwa in „What a Wonderful World“.', '{"en":{"explanation":"He was also famous for his gravelly singing voice, for example in “What a Wonderful World”."}}'::jsonb),
  ('c28', 2, 'Der Louvre ist das meistbesuchte Kunstmuseum der Welt.', '{"en":{"explanation":"The Louvre is the most visited art museum in the world."}}'::jsonb),
  ('c29', 3, '„Renaissance“ bedeutet Wiedergeburt. Sie begann im 14. und 15. Jahrhundert in Italien.', '{"en":{"explanation":"“Renaissance” means rebirth. It began in Italy in the 14th and 15th centuries."}}'::jsonb),
  ('c30', 1, 'Die vier Violinkonzerte erschienen 1725 und gehören zu den bekanntesten Werken des Barock.', '{"en":{"explanation":"The four violin concertos were published in 1725 and are among the best-known works of the Baroque."}}'::jsonb),
  ('c31', 2, 'Es wird alle fünf Jahre von den Bürgerinnen und Bürgern der EU gewählt.', '{"en":{"explanation":"It is elected every five years by the citizens of the EU."}}'::jsonb),
  ('c32', 3, 'Die Vereinten Nationen verabschiedeten sie am 10. Dezember 1948 – heute der Tag der Menschenrechte.', '{"en":{"explanation":"The United Nations adopted it on 10 December 1948 – now Human Rights Day."}}'::jsonb),
  ('c33', 0, 'Monets Bild „Impression, Sonnenaufgang“ von 1872 gab der Bewegung ihren Namen.', '{"en":{"explanation":"Monet''s 1872 painting “Impression, Sunrise” gave the movement its name."}}'::jsonb),
  ('c34', 1, 'Hamlet, Prinz von Dänemark, grübelt in diesem Monolog über Leben und Tod.', '{"en":{"explanation":"In this soliloquy Hamlet, Prince of Denmark, broods over life and death."}}'::jsonb),
  ('mf1', 0, 'Es sind zwei Schreibweisen derselben Zahl. Ein Beweis: 1/3 = 0,333…, und dreimal 1/3 ist 1.', '{"en":{"explanation":"They are two ways of writing the same number. One proof: 1/3 = 0.333…, and three times 1/3 is 1."}}'::jsonb),
  ('mm1', 1, 'Die Münze hat kein Gedächtnis: Bei jedem Wurf stehen die Chancen wieder 50 zu 50. Der Irrtum heißt Spielerfehlschluss.', '{"en":{"explanation":"The coin has no memory: on every toss the odds are 50:50 again. The error is called the gambler''s fallacy."}}'::jsonb),
  ('mf2', 0, 'Die Wahrscheinlichkeit liegt knapp über 50 Prozent, weil es bei 23 Personen bereits 253 mögliche Paare gibt.', '{"en":{"explanation":"The probability is just over 50 percent, because 23 people already form 253 possible pairs."}}'::jsonb),
  ('mm2', 1, 'Null ist gerade: Sie lässt sich ohne Rest durch 2 teilen und liegt zwischen den ungeraden Zahlen −1 und 1.', '{"en":{"explanation":"Zero is even: it can be divided by 2 without a remainder and lies between the odd numbers −1 and 1."}}'::jsonb),
  ('lf1', 0, 'Das große ẞ wurde 2017 in die amtliche deutsche Rechtschreibung aufgenommen – nützlich etwa für Namen in Großbuchstaben.', '{"en":{"explanation":"The capital ẞ was added to the official German spelling rules in 2017 – useful, for example, for names written in capitals."}}'::jsonb),
  ('lm1', 1, 'Das ist ein beliebter Mythos. Ihre Sprachen bilden lange zusammengesetzte Wörter; die Zahl der eigentlichen Wortstämme für Schnee ist ähnlich klein wie in anderen Sprachen.', '{"en":{"explanation":"This is a popular myth. Their languages form long compound words; the number of actual word roots for snow is about as small as in other languages."}}'::jsonb),
  ('lf2', 0, 'Es geht auf „robota“ (Fronarbeit) zurück und wurde 1920 durch das Theaterstück „R.U.R.“ von Karel Čapek bekannt.', '{"en":{"explanation":"It goes back to “robota” (forced labour) and became known in 1920 through the play “R.U.R.” by Karel Čapek."}}'::jsonb),
  ('sf6', 0, 'Schimpansen und Bonobos sind unsere nächsten lebenden Verwandten. Die gemeinsamen Vorfahren lebten vor etwa sechs bis sieben Millionen Jahren.', '{"en":{"explanation":"Chimpanzees and bonobos are our closest living relatives. Our common ancestors lived about six to seven million years ago."}}'::jsonb),
  ('tf5', 0, 'Der Programmierer Ray Tomlinson verschickte sie im ARPANET – und führte dabei das @-Zeichen in Adressen ein.', '{"en":{"explanation":"The programmer Ray Tomlinson sent it on the ARPANET – and introduced the @ sign in addresses in the process."}}'::jsonb),
  ('hf5', 0, 'Das Frauenwahlrecht wurde im November 1918 eingeführt; im Januar 1919 konnten Frauen erstmals bei einer landesweiten Wahl abstimmen.', '{"en":{"explanation":"Women''s suffrage was introduced in November 1918; in January 1919 women were able to vote in a nationwide election for the first time."}}'::jsonb),
  ('gf3', 0, 'Als Wüste gilt ein Gebiet mit sehr wenig Niederschlag – egal ob heiß oder kalt. Die Antarktis ist größer als die Sahara, die größte heiße Wüste.', '{"en":{"explanation":"A desert is an area with very little precipitation – whether hot or cold. Antarctica is larger than the Sahara, the largest hot desert."}}'::jsonb),
  ('gm4', 1, 'In den Höckern steckt Fett als Energiereserve. Wasser speichern Kamele vor allem im Blut und im Gewebe.', '{"en":{"explanation":"The humps contain fat as an energy reserve. Camels store water mainly in their blood and tissue."}}'::jsonb),
  ('ef3', 0, 'Das Konzept wurde 2008 unter dem Pseudonym Satoshi Nakamoto veröffentlicht; im Januar 2009 entstand der erste Block.', '{"en":{"explanation":"The concept was published in 2008 under the pseudonym Satoshi Nakamoto; the first block was created in January 2009."}}'::jsonb),
  ('cf3', 0, 'Ein ehemaliger Mitarbeiter des Museums nahm das Bild mit. Erst mehr als zwei Jahre später tauchte es in Italien wieder auf – der Diebstahl machte es weltberühmt.', '{"en":{"explanation":"A former employee of the museum took the painting. It only resurfaced in Italy more than two years later – the theft made it world-famous."}}'::jsonb),
  ('cm4', 1, 'Ihn wählt die Bundesversammlung: alle Bundestagsabgeordneten und ebenso viele Vertreter der Bundesländer.', '{"en":{"explanation":"The President is elected by the Federal Convention: all members of the Bundestag and an equal number of representatives of the federal states."}}'::jsonb)
insert into public.videos (id, category_id, title, hook, description, video_url, thumbnail_url, duration_seconds, has_audio, captions, creator_name, format, sources, published_at, tags, quiz_question_id, verification_status, status, min_age, start_seconds, end_seconds, license, translations) values
  ('v-venus', 'science', 'Auf der Venus ist ein Tag länger als ein Jahr', '243 Erdtage für eine Drehung, nur 225 für einen Umlauf um die Sonne.', 'Die Venus dreht sich extrem langsam – und noch dazu rückwärts. Deshalb dauert eine Drehung um die eigene Achse länger als ein kompletter Umlauf um die Sonne.', '/clips/v-venus.mp4', null, 7.27, true, '["Die Venus dreht sich so langsam,","dass ein Tag dort länger dauert","als ein ganzes Jahr."]'::jsonb, 'Wunder Redaktion', 'animated_fact', '[{"name":"Wikipedia: Venus (Planet)","url":"https://de.wikipedia.org/wiki/Venus_(Planet)"}]'::jsonb, '2026-10-09T12:00:00Z', array['Planeten', 'Sonnensystem']::text[], 'q-v-venus', 'ai_checked', 'archived', 10, null, null, null, '{}'::jsonb),
  ('v-kleopatra', 'history', 'Kleopatra lebte näher an der Mondlandung als am Pyramidenbau', 'Das alte Ägypten dauerte so lange, dass seine Anfänge für Kleopatra schon Altertum waren.', 'Die Cheops-Pyramide entstand um 2560 v. Chr. Kleopatra starb 30 v. Chr. – rund 2500 Jahre später. Bis zur Mondlandung 1969 vergingen danach nur etwa 2000 Jahre.', '/clips/v-kleopatra.mp4', null, 6.91, true, '["Kleopatra lebte näher","an der Mondlandung","als am Bau der großen Pyramide."]'::jsonb, 'Wunder Redaktion', 'animated_fact', '[{"name":"Wikipedia: Kleopatra VII.","url":"https://de.wikipedia.org/wiki/Kleopatra_VII."},{"name":"Wikipedia: Cheops-Pyramide","url":"https://de.wikipedia.org/wiki/Cheops-Pyramide"}]'::jsonb, '2026-10-08T12:00:00Z', array['Ägypten', 'Zeitgefühl']::text[], 'q-v-kleopatra', 'ai_checked', 'archived', 10, null, null, null, '{}'::jsonb),
  ('v-apollo', 'technology', 'Zum Mond mit 4 Kilobyte Arbeitsspeicher', 'Der Apollo-Bordcomputer hatte millionenfach weniger Speicher als ein Smartphone.', 'Der Apollo Guidance Computer hatte 2048 Wörter beschreibbaren Speicher, etwa 4 Kilobyte. Ein Smartphone mit 8 Gigabyte hat rund zwei Millionen Mal so viel.', '/clips/v-apollo.mp4', null, 11.3, true, '["Der Computer, der Menschen zum Mond brachte,","hatte rund vier Kilobyte Arbeitsspeicher.","Ein Smartphone hat millionenfach mehr."]'::jsonb, 'Wunder Redaktion', 'animated_fact', '[{"name":"Wikipedia: Apollo Guidance Computer","url":"https://de.wikipedia.org/wiki/Apollo_Guidance_Computer"}]'::jsonb, '2026-10-10T12:00:00Z', array['Raumfahrt', 'Computer']::text[], 'q-v-apollo', 'ai_checked', 'archived', 10, null, null, null, '{}'::jsonb),
  ('v-luft', 'science', 'Was du gerade einatmest, ist vor allem Stickstoff', 'Luft besteht zu etwa 78 % aus Stickstoff und nur zu 21 % aus Sauerstoff.', 'Trockene Luft enthält rund 78 % Stickstoff, 21 % Sauerstoff und knapp 1 % Argon. Kohlendioxid macht nur einen Bruchteil eines Prozents aus.', '/clips/v-luft.mp4', null, 9.63, true, '["Die Luft, die du atmest,","besteht nur zu einem Fünftel aus Sauerstoff.","Der größte Teil ist Stickstoff."]'::jsonb, 'Wunder Redaktion', 'animated_fact', '[{"name":"Wikipedia: Erdatmosphäre","url":"https://de.wikipedia.org/wiki/Erdatmosphäre"}]'::jsonb, '2026-10-05T12:00:00Z', array['Atmosphäre', 'Chemie']::text[], 'q-v-luft', 'ai_checked', 'archived', 10, null, null, null, '{}'::jsonb),
  ('v-ozean', 'earth', 'Der blaue Planet: mehr Wasser als Land', 'Rund 71 % der Erdoberfläche sind von Wasser bedeckt.', 'Ozeane und Meere bedecken etwa 71 % der Erdoberfläche. Landflächen machen rund 29 % aus – weniger als ein Drittel.', '/clips/v-ozean.mp4', null, 9.26, true, '["Rund 71 Prozent der Erdoberfläche","sind von Wasser bedeckt.","Land macht weniger als ein Drittel aus."]'::jsonb, 'Wunder Redaktion', 'animated_fact', '[{"name":"Wikipedia: Erde","url":"https://de.wikipedia.org/wiki/Erde"}]'::jsonb, '2026-10-07T12:00:00Z', array['Ozeane', 'Geografie']::text[], 'q-v-ozean', 'ai_checked', 'archived', 10, null, null, null, '{}'::jsonb),
  ('v-oxford', 'history', 'Oxford ist älter als das Reich der Azteken', 'In Oxford wurde schon um 1096 gelehrt, Tenochtitlan entstand erst um 1325.', 'Die Lehre in Oxford ist seit etwa 1096 belegt. Tenochtitlan, die Hauptstadt der Azteken, wurde um 1325 gegründet – mehr als zwei Jahrhunderte später.', '/clips/v-oxford.mp4', null, 7.04, true, '["In Oxford wurde schon gelehrt,","als es die Hauptstadt der Azteken","noch gar nicht gab."]'::jsonb, 'Wunder Redaktion', 'animated_fact', '[{"name":"Wikipedia: University of Oxford","url":"https://de.wikipedia.org/wiki/University_of_Oxford"},{"name":"Wikipedia: Tenochtitlan","url":"https://de.wikipedia.org/wiki/Tenochtitlan"}]'::jsonb, '2026-10-03T12:00:00Z', array['Mittelalter', 'Zeitgefühl']::text[], 'q-v-oxford', 'ai_checked', 'archived', 10, null, null, null, '{}'::jsonb),
  ('v-iss-nacht', 'earth', 'Die Erde bei Nacht – gesehen von der Raumstation', 'Die ISS umrundet die Erde etwa alle 90 Minuten – rund 16 Mal am Tag.', 'Die Internationale Raumstation fliegt in rund 400 Kilometern Höhe mit etwa 28.000 km/h. Der farbige Schimmer über dem Horizont ist das Nachthimmelsleuchten der oberen Atmosphäre.', '/clips/v-iss-nacht.mp4', '/clips/v-iss-nacht.jpg', 10, false, '["So sieht die Erde nachts aus dem All aus.","Die Raumstation fliegt mit rund 28.000 km/h.","Alle 90 Minuten umrundet sie die Erde."]'::jsonb, 'NASA', 'footage', '[{"name":"NASA Image and Video Library","url":"https://images.nasa.gov/details/GSFC_20180124_m12825_ISS_Airglow"}]'::jsonb, '2026-10-12T12:00:00Z', array['ISS', 'Raumfahrt', 'Atmosphäre']::text[], 'q-v-iss-nacht', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"Earth at night – seen from the space station","hook":"The ISS circles the Earth about every 90 minutes – roughly 16 times a day.","description":"The International Space Station flies at an altitude of about 400 kilometres at roughly 28,000 km/h. The coloured shimmer above the horizon is airglow in the upper atmosphere.","captions":["This is what Earth looks like at night from space.","The space station travels at about 28,000 km/h.","It circles the Earth every 90 minutes."]}}'::jsonb),
  ('v-saturn-v', 'history', 'Der Start von Apollo 11', 'Am 16. Juli 1969 hob die Saturn V ab – vier Tage später landeten Menschen auf dem Mond.', 'Die Saturn V war rund 110 Meter hoch und ist bis heute eine der stärksten Raketen, die je geflogen sind. An Bord von Apollo 11: Neil Armstrong, Buzz Aldrin und Michael Collins.', '/clips/v-saturn-v.mp4', '/clips/v-saturn-v.jpg', 4.3, false, '["16. Juli 1969: Apollo 11 startet.","Die Saturn-V-Rakete ist 110 Meter hoch.","Ihr Ziel: der Mond."]'::jsonb, 'NASA', 'footage', '[{"name":"NASA Image and Video Library","url":"https://images.nasa.gov/details/Apollo_11_Intro_720p"}]'::jsonb, '2026-10-11T12:00:00Z', array['Apollo', 'Raumfahrt', 'Mondlandung']::text[], 'q-v-saturn-v', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"The launch of Apollo 11","hook":"On 16 July 1969 the Saturn V lifted off – four days later humans landed on the Moon.","description":"The Saturn V was about 110 metres tall and remains one of the most powerful rockets ever flown. On board Apollo 11: Neil Armstrong, Buzz Aldrin and Michael Collins.","captions":["16 July 1969: Apollo 11 lifts off.","The Saturn V rocket is 110 metres tall.","Its destination: the Moon."]}}'::jsonb),
  ('v-aldrin', 'history', 'Der zweite Mensch auf dem Mond', 'Buzz Aldrin stieg rund 19 Minuten nach Neil Armstrong die Leiter der Mondfähre hinab.', 'Originalaufnahme der Fernsehübertragung vom 20. Juli 1969 in restaurierter Fassung. Rund 600 Millionen Menschen verfolgten die Mondlandung live.', '/clips/v-aldrin.mp4', '/clips/v-aldrin.jpg', 10, false, '["20. Juli 1969, Meer der Ruhe.","Buzz Aldrin steigt die Leiter hinab.","Er ist der zweite Mensch auf dem Mond."]'::jsonb, 'NASA', 'footage', '[{"name":"NASA Image and Video Library","url":"https://images.nasa.gov/details/Buzz_Descends_Comparison__720p"}]'::jsonb, '2026-10-10T12:00:00Z', array['Apollo', 'Mondlandung']::text[], 'q-v-aldrin', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"The second human on the Moon","hook":"Buzz Aldrin climbed down the lunar module''s ladder about 19 minutes after Neil Armstrong.","description":"Original footage from the television broadcast of 20 July 1969 in a restored version. Around 600 million people watched the Moon landing live.","captions":["20 July 1969, Sea of Tranquility.","Buzz Aldrin climbs down the ladder.","He is the second human on the Moon."]}}'::jsonb),
  ('v-ingenuity', 'technology', 'Ein Hubschrauber auf dem Mars', 'Ingenuity gelang 2021 der erste motorisierte Flug auf einem anderen Planeten.', 'Animation der NASA. Die Marsluft ist rund hundertmal dünner als die der Erde, deshalb drehen sich die Rotoren von Ingenuity mit etwa 2.400 Umdrehungen pro Minute. Geplant waren fünf Flüge – es wurden 72.', '/clips/v-ingenuity.mp4', '/clips/v-ingenuity.jpg', 10, false, '["Das ist Ingenuity, ein Hubschrauber für den Mars.","Die Luft dort ist hundertmal dünner als auf der Erde.","Trotzdem flog er 72 Mal."]'::jsonb, 'NASA', 'footage', '[{"name":"NASA Image and Video Library","url":"https://images.nasa.gov/details/JPL-20200429-TECHf-0002-Mars%20Helicopter%20Animation"}]'::jsonb, '2026-10-09T12:00:00Z', array['Mars', 'Raumfahrt', 'Robotik']::text[], 'q-v-ingenuity', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"A helicopter on Mars","hook":"In 2021 Ingenuity made the first powered flight on another planet.","description":"NASA animation. The Martian air is about a hundred times thinner than Earth''s, so Ingenuity''s rotors spin at around 2,400 revolutions per minute. Five flights were planned – it made 72.","captions":["This is Ingenuity, a helicopter built for Mars.","The air there is a hundred times thinner than on Earth.","It still flew 72 times."]}}'::jsonb),
  ('v-sonne', 'science', 'Unsere Sonne in Bewegung', 'Die Sonne enthält mehr als 99,8 Prozent der gesamten Masse unseres Sonnensystems.', 'Zeitrafferaufnahmen des Sonnenobservatoriums SDO im ultravioletten Licht. Die Sonne ist eine Kugel aus heißem Plasma und besteht vor allem aus Wasserstoff und Helium.', '/clips/v-sonne.mp4', '/clips/v-sonne.jpg', 10, false, '["Das ist unsere Sonne im ultravioletten Licht.","Ihre Oberfläche ist ständig in Bewegung.","Sie enthält 99,8 Prozent der Masse des Sonnensystems."]'::jsonb, 'NASA', 'footage', '[{"name":"NASA Image and Video Library","url":"https://images.nasa.gov/details/GSFC_20160212_SDO_m12144_Year6"}]'::jsonb, '2026-10-08T12:00:00Z', array['Sonne', 'Astronomie']::text[], 'q-v-sonne', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"Our Sun in motion","hook":"The Sun contains more than 99.8 percent of the total mass of our solar system.","description":"Time-lapse footage from the Solar Dynamics Observatory in ultraviolet light. The Sun is a ball of hot plasma made mostly of hydrogen and helium.","captions":["This is our Sun in ultraviolet light.","Its surface is constantly in motion.","It contains 99.8 percent of the solar system''s mass."]}}'::jsonb),
  ('v-hurrikan', 'earth', 'Ein Hurrikan aus dem All', 'Im Auge eines Hurrikans ist es fast windstill – ringsum toben die stärksten Winde.', 'Hurrikan Dorian am 1. September 2019, aufgenommen von Kameras an der Internationalen Raumstation. Tropische Wirbelstürme entstehen über warmem Meerwasser ab etwa 26 Grad.', '/clips/v-hurrikan.mp4', '/clips/v-hurrikan.jpg', 10, false, '["Hurrikan Dorian, gefilmt von der Raumstation.","In der Mitte liegt das fast windstille Auge.","Ringsum toben die stärksten Winde."]'::jsonb, 'NASA', 'footage', '[{"name":"NASA Image and Video Library","url":"https://images.nasa.gov/details/jsc2019m000805_Hurricane_Dorian_190901"}]'::jsonb, '2026-10-07T12:00:00Z', array['Wetter', 'Hurrikan', 'ISS']::text[], 'q-v-hurrikan', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"A hurricane seen from space","hook":"The eye of a hurricane is almost calm – the strongest winds rage all around it.","description":"Hurricane Dorian on 1 September 2019, filmed by cameras on the International Space Station. Tropical cyclones form over warm sea water of about 26 degrees or more.","captions":["Hurricane Dorian, filmed from the space station.","In the middle lies the almost windless eye.","The strongest winds rage all around it."]}}'::jsonb),
  ('v-blitz', 'science', 'Ein Blitz in Zeitlupe', 'Ein Blitz heizt die Luft auf bis zu 30.000 Grad auf – heißer als die Oberfläche der Sonne.', 'Zeitlupenaufnahme mit 240 Bildern pro Sekunde, Finnland. Die schlagartig erhitzte Luft dehnt sich explosionsartig aus: Das hören wir als Donner.', '/clips/v-blitz.mp4', '/clips/v-blitz.jpg', 6, false, '["Ein Blitz, zehnfach verlangsamt.","Er erhitzt die Luft auf bis zu 30.000 Grad.","Die Druckwelle hören wir als Donner."]'::jsonb, 'MrNousia', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:Lightning_strikes_in_slow_motion_(240fps)_in_Muurame,_Finland.webm"}]'::jsonb, '2026-10-06T12:00:00Z', array['Wetter', 'Physik']::text[], 'q-v-blitz', 'ai_checked', 'published', 10, null, null, 'CC BY 3.0, MrNousia – bearbeitet (Ausschnitt, Hochformat)', '{"en":{"title":"Lightning in slow motion","hook":"A lightning bolt heats the air to as much as 30,000 degrees – hotter than the surface of the Sun.","description":"Slow-motion footage at 240 frames per second, Finland. The suddenly heated air expands explosively: we hear that as thunder.","captions":["A lightning bolt, slowed down tenfold.","It heats the air to as much as 30,000 degrees.","We hear the shock wave as thunder."]}}'::jsonb),
  ('v-polarlicht', 'science', 'Polarlichter über Alaska', 'Polarlichter entstehen, wenn geladene Teilchen von der Sonne auf die obere Atmosphäre treffen.', 'Zeitraffer aus Alaska. Das grüne Leuchten stammt von Sauerstoffatomen in rund 100 Kilometern Höhe, die durch die Teilchen des Sonnenwinds angeregt werden.', '/clips/v-polarlicht.mp4', '/clips/v-polarlicht.jpg', 8.5, false, '["Polarlichter über Alaska im Zeitraffer.","Teilchen von der Sonne treffen auf die Atmosphäre.","Grün leuchtet der Sauerstoff."]'::jsonb, 'NASA Scientific Visualization Studio', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:Alaskan_Aurora_Time_Lapse_(SVS15077).webm"}]'::jsonb, '2026-10-05T12:00:00Z', array['Sonne', 'Atmosphäre']::text[], 'q-v-polarlicht', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"Northern lights over Alaska","hook":"Auroras occur when charged particles from the Sun hit the upper atmosphere.","description":"Time-lapse from Alaska. The green glow comes from oxygen atoms about 100 kilometres up that are excited by solar wind particles.","captions":["Northern lights over Alaska in time-lapse.","Particles from the Sun hit the atmosphere.","The green glow is oxygen."]}}'::jsonb),
  ('v-keimung', 'science', 'Aus Samen werden Pflanzen', 'Ein Samen enthält einen winzigen Keimling und Nahrung für den Start – Wasser weckt ihn auf.', 'Linsen keimen im Zeitraffer. Zum Keimen braucht ein Samen Wasser, Wärme und Sauerstoff. Licht wird erst wichtig, wenn die ersten Blätter erscheinen.', '/clips/v-keimung.mp4', '/clips/v-keimung.jpg', 11, false, '["Linsen keimen im Zeitraffer.","Im Samen steckt Nahrung für den Start.","Wasser weckt den Keimling auf."]'::jsonb, 'Always Shooting', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:Lentil_microgreens_growth_time_lapse.webm"}]'::jsonb, '2026-10-04T12:00:00Z', array['Pflanzen', 'Biologie']::text[], 'q-v-keimung', 'ai_checked', 'published', 6, null, null, 'CC BY 2.0, Always Shooting – bearbeitet (Ausschnitt, Hochformat)', '{"en":{"title":"From seed to plant","hook":"A seed contains a tiny embryo and food for the start – water wakes it up.","description":"Lentils sprouting in time-lapse. To germinate, a seed needs water, warmth and oxygen. Light only becomes important once the first leaves appear.","captions":["Lentils sprouting in time-lapse.","The seed holds food for the start.","Water wakes the embryo up."]}}'::jsonb),
  ('v-tacoma', 'technology', 'Die Brücke, die sich selbst zerriss', '1940 versetzte Wind die Tacoma-Narrows-Brücke in immer stärkere Schwingungen – bis sie einstürzte.', 'Die Hängebrücke im US-Bundesstaat Washington war erst vier Monate alt. Seit dem Einsturz werden große Brücken im Windkanal getestet. Verletzt wurde niemand.', '/clips/v-tacoma.mp4', '/clips/v-tacoma.jpg', 8, false, '["Tacoma, USA, 7. November 1940.","Der Wind lässt die Fahrbahn schwingen.","Wenig später stürzt die Brücke ein."]'::jsonb, 'Barney Elliot', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:Tacoma_Narrows_Bridge_destruction.ogv"}]'::jsonb, '2026-10-03T12:00:00Z', array['Ingenieurwesen', 'Physik']::text[], 'q-v-tacoma', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"The bridge that tore itself apart","hook":"In 1940 wind set the Tacoma Narrows Bridge swinging more and more violently – until it collapsed.","description":"The suspension bridge in the US state of Washington was only four months old. Since the collapse, large bridges have been tested in wind tunnels. Nobody was hurt.","captions":["Tacoma, USA, 7 November 1940.","The wind makes the roadway oscillate.","A little later the bridge collapses."]}}'::jsonb),
  ('v-3d-druck', 'technology', 'So arbeitet ein 3D-Drucker', 'Ein 3D-Drucker baut Gegenstände Schicht für Schicht aus geschmolzenem Kunststoff auf.', 'Zeitraffer eines Druckvorgangs. Die Düse fährt jede Schicht nach einem digitalen Bauplan ab; was hier Sekunden dauert, braucht in Wirklichkeit oft Stunden.', '/clips/v-3d-druck.mp4', '/clips/v-3d-druck.jpg', 6, false, '["Ein 3D-Drucker im Zeitraffer.","Schicht für Schicht wächst die Figur.","Der Bauplan kommt aus dem Computer."]'::jsonb, 'RepRapPro', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:Robot_3D_print_timelapse_on_RepRapPro_Fisher.webm"}]'::jsonb, '2026-10-02T12:00:00Z', array['Fertigung', 'Maker']::text[], 'q-v-3d-druck', 'ai_checked', 'published', 10, null, null, 'CC BY 3.0, RepRapPro – bearbeitet (Ausschnitt, Hochformat)', '{"en":{"title":"How a 3D printer works","hook":"A 3D printer builds objects layer by layer from molten plastic.","description":"Time-lapse of a print. The nozzle traces each layer from a digital blueprint; what takes seconds here often takes hours in reality.","captions":["A 3D printer in time-lapse.","The figure grows layer by layer.","The blueprint comes from a computer."]}}'::jsonb),
  ('v-mars-landung', 'technology', 'Landung auf dem Mars – mit Bordkamera', 'So sah der Rover Perseverance 2021 seine eigene Landung auf dem Mars.', 'Blick der Bordkamera nach unten auf den Krater Jezero, 18. Februar 2021. Auf den letzten Metern ließ eine schwebende Plattform den Rover an Seilen herab.', '/clips/v-mars-landung.mp4', '/clips/v-mars-landung.jpg', 10, false, '["18. Februar 2021: Anflug auf den Mars.","Die Bordkamera blickt auf den Krater Jezero.","Sekunden später setzt der Rover auf."]'::jsonb, 'NASA', 'footage', '[{"name":"NASA Image and Video Library","url":"https://images.nasa.gov/details/JPL-20210222-M2020f-0001-Perseverance%20Rover%E2%80%99s%20Descent%20and%20Touchdown%20on%20Mars"}]'::jsonb, '2026-10-01T12:00:00Z', array['Mars', 'Raumfahrt']::text[], 'q-v-mars-landung', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"Landing on Mars – onboard camera","hook":"This is how the rover Perseverance saw its own landing on Mars in 2021.","description":"The onboard camera looks down at Jezero Crater, 18 February 2021. For the final metres, a hovering platform lowered the rover on cables.","captions":["18 February 2021: approaching Mars.","The onboard camera looks at Jezero Crater.","Seconds later the rover touches down."]}}'::jsonb),
  ('v-erdaufgang', 'history', 'Der erste Erdaufgang', 'An Heiligabend 1968 sahen Menschen zum ersten Mal die Erde über dem Mond aufgehen.', 'Die Besatzung von Apollo 8 umkreiste als erste den Mond. Die Visualisierung der NASA rekonstruiert den Moment, in dem William Anders das berühmte Foto „Earthrise“ aufnahm.', '/clips/v-erdaufgang.mp4', '/clips/v-erdaufgang.jpg', 10, false, '["24. Dezember 1968, Mondumlaufbahn.","Über dem Horizont geht die Erde auf.","Drei Menschen sehen das als Erste."]'::jsonb, 'NASA / Goddard Space Flight Center', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:Earthrise.ogv"}]'::jsonb, '2026-09-30T12:00:00Z', array['Apollo', 'Raumfahrt']::text[], 'q-v-erdaufgang', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"The first Earthrise","hook":"On Christmas Eve 1968, humans saw the Earth rise over the Moon for the first time.","description":"The crew of Apollo 8 were the first to orbit the Moon. NASA''s visualisation reconstructs the moment William Anders took the famous “Earthrise” photograph.","captions":["24 December 1968, lunar orbit.","The Earth rises above the horizon.","Three people are the first to see it."]}}'::jsonb),
  ('v-titanic', 'history', 'Die Titanic vor ihrer ersten Fahrt', 'Die Titanic war 269 Meter lang und galt 1912 als größtes Schiff der Welt.', 'Zeitgenössische Filmaufnahmen aus dem Archiv von British Pathé (1911–1912). Auf ihrer Jungfernfahrt stieß die Titanic mit einem Eisberg zusammen und sank am 15. April 1912; rund 1.500 Menschen starben.', '/clips/v-titanic.mp4', '/clips/v-titanic.jpg', 8, false, '["Aufnahmen aus den Jahren 1911 und 1912.","Die Titanic ist 269 Meter lang.","Ihre erste Fahrt ist auch ihre letzte."]'::jsonb, 'British Pathé', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:Titanic_Disaster_-_Genuine_Footage_(1911-1912)(enhanced).webm"}]'::jsonb, '2026-09-29T12:00:00Z', array['Schifffahrt', '20. Jahrhundert']::text[], 'q-v-titanic', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"The Titanic before her maiden voyage","hook":"The Titanic was 269 metres long and in 1912 was considered the largest ship in the world.","description":"Contemporary film footage from the British Pathé archive (1911–1912). On her maiden voyage the Titanic struck an iceberg and sank on 15 April 1912; about 1,500 people died.","captions":["Footage from 1911 and 1912.","The Titanic is 269 metres long.","Her first voyage is also her last."]}}'::jsonb),
  ('v-flugpioniere', 'history', 'Als das Fliegen begann', '1903 gelang den Brüdern Wright der erste gesteuerte Motorflug – er dauerte zwölf Sekunden.', 'Filmaufnahmen früher Flugzeuge aus den ersten Jahren der Luftfahrt. Nur 66 Jahre nach dem ersten Motorflug landeten Menschen auf dem Mond.', '/clips/v-flugpioniere.mp4', '/clips/v-flugpioniere.jpg', 4, false, '["Flugzeuge aus den Anfangsjahren der Luftfahrt.","1903 flogen die Brüder Wright zwölf Sekunden.","66 Jahre später: die Mondlandung."]'::jsonb, 'Unbekannt (gemeinfrei)', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:First_flights_in_aviation_history.ogv"}]'::jsonb, '2026-09-28T12:00:00Z', array['Luftfahrt']::text[], 'q-v-flugpioniere', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"When flying began","hook":"In 1903 the Wright brothers made the first controlled powered flight – it lasted twelve seconds.","description":"Film footage of early aircraft from the first years of aviation. Only 66 years after the first powered flight, humans landed on the Moon.","captions":["Aircraft from the early years of aviation.","In 1903 the Wright brothers flew for twelve seconds.","66 years later: the Moon landing."]}}'::jsonb),
  ('v-buchdruck', 'history', 'Drucken wie zu Gutenbergs Zeit', 'Hochdruck: Farbe kommt auf erhabene Lettern, dann wird Papier dagegengepresst.', 'Eine Tiegeldruckpresse in Indien. Das Prinzip geht auf Johannes Gutenberg zurück, der um 1450 in Mainz den Druck mit beweglichen Metalllettern entwickelte.', '/clips/v-buchdruck.mp4', '/clips/v-buchdruck.jpg', 10, false, '["Eine Druckpresse mit beweglichen Lettern.","Walzen tragen die Farbe auf.","Das Prinzip stammt von Gutenberg, um 1450."]'::jsonb, 'Subhashish Panigrahi', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:Printing_in_a_letterpress.webm"}]'::jsonb, '2026-09-27T12:00:00Z', array['Buchdruck', 'Medien']::text[], 'q-v-buchdruck', 'ai_checked', 'published', 10, null, null, 'CC BY-SA 4.0, Subhashish Panigrahi – bearbeitet (Ausschnitt, Hochformat)', '{"en":{"title":"Printing as in Gutenberg''s day","hook":"Letterpress: ink is applied to raised type, then paper is pressed against it.","description":"A platen press in India. The principle goes back to Johannes Gutenberg, who developed printing with movable metal type in Mainz around 1450.","captions":["A printing press with movable type.","Rollers apply the ink.","The principle is Gutenberg''s, from around 1450."]}}'::jsonb),
  ('v-lumiere', 'culture', 'Einer der ersten Filme der Welt', '1895 zeigten die Brüder Lumière in Paris erstmals Filme vor zahlendem Publikum – die Geburt des Kinos.', '„Die Ankunft eines Zuges auf dem Bahnhof in La Ciotat“, gedreht Mitte der 1890er-Jahre. Dass die Zuschauer vor dem Zug aus dem Saal flohen, ist eine beliebte, aber unbelegte Legende.', '/clips/v-lumiere.mp4', '/clips/v-lumiere.jpg', 8, false, '["Frankreich, Mitte der 1890er-Jahre.","Ein Zug fährt in den Bahnhof ein.","So begann das Kino."]'::jsonb, 'Auguste und Louis Lumière', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:L%27Arriv%C3%A9e_d%27un_train_en_gare_de_La_Ciotat_(1897).webm"}]'::jsonb, '2026-09-26T12:00:00Z', array['Film', 'Kino']::text[], 'q-v-lumiere', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"One of the world''s first films","hook":"In 1895 the Lumière brothers showed films to a paying audience in Paris for the first time – the birth of cinema.","description":"“The Arrival of a Train at La Ciotat Station”, shot in the mid-1890s. That audiences fled the room from the train is a popular but unproven legend.","captions":["France, mid-1890s.","A train pulls into the station.","This is how cinema began."]}}'::jsonb),
  ('v-roundhay', 'culture', 'Der älteste erhaltene Film', 'Diese zwei Sekunden aus einem Garten in Leeds sind der älteste erhaltene Film der Welt – gedreht 1888.', '„Roundhay Garden Scene“ von Louis Le Prince, aufgenommen am 14. Oktober 1888 in England. Der Clip zeigt die Szene mehrmals hintereinander.', '/clips/v-roundhay.mp4', '/clips/v-roundhay.jpg', 8, false, '["Leeds, England, 14. Oktober 1888.","Vier Menschen gehen durch einen Garten.","Es ist der älteste erhaltene Film."]'::jsonb, 'Louis Le Prince', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:Roundhay_Garden_Scene_(1888).webm"}]'::jsonb, '2026-09-25T12:00:00Z', array['Film', 'Erfindungen']::text[], 'q-v-roundhay', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"The oldest surviving film","hook":"These two seconds from a garden in Leeds are the oldest surviving film in the world – shot in 1888.","description":"“Roundhay Garden Scene” by Louis Le Prince, filmed in England on 14 October 1888. The clip shows the scene several times in a row.","captions":["Leeds, England, 14 October 1888.","Four people walk through a garden.","It is the oldest surviving film."]}}'::jsonb),
  ('v-reise-zum-mond', 'culture', 'Der erste Science-Fiction-Film', '„Die Reise zum Mond“ von 1902 gilt als erster Science-Fiction-Film der Geschichte.', 'Der französische Zauberkünstler Georges Méliès erfand für seine Filme Tricks wie Stopptrick und Mehrfachbelichtung. Jede Kulisse war von Hand gemalt.', '/clips/v-reise-zum-mond.mp4', '/clips/v-reise-zum-mond.jpg', 8, false, '["Frankreich, 1902.","Georges Méliès schickt Forscher zum Mond.","Alle Tricks entstehen direkt in der Kamera."]'::jsonb, 'Georges Méliès', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:Le_Voyage_dans_la_Lune_(1902).webm"}]'::jsonb, '2026-09-24T12:00:00Z', array['Film', 'Science-Fiction']::text[], 'q-v-reise-zum-mond', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"The first science-fiction film","hook":"“A Trip to the Moon” from 1902 is regarded as the first science-fiction film in history.","description":"The French stage magician Georges Méliès invented tricks such as the stop trick and multiple exposure for his films. Every set was painted by hand.","captions":["France, 1902.","Georges Méliès sends explorers to the Moon.","All the tricks are created in the camera."]}}'::jsonb),
  ('v-orchester', 'culture', 'Wie ein Orchester aufgebaut ist', 'Ein Sinfonieorchester hat vier Gruppen: Streicher, Holzbläser, Blechbläser und Schlagwerk.', 'Das Sinfonieorchester der University of Colorado Boulder spielt Beethovens 5. Sinfonie. Vorn sitzen die Streicher, dahinter die Bläser, ganz hinten das Schlagwerk.', '/clips/v-orchester.mp4', '/clips/v-orchester.jpg', 8, false, '["Ein Sinfonieorchester bei der Arbeit.","Vorn die Streicher, dahinter die Bläser.","Der Dirigent hält alle zusammen."]'::jsonb, 'University of Colorado Boulder College of Music', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:Beethoven_Symphony_No._5,_Mvmt_1_-_University_of_Colorado_Boulder_Symphony_Orchestra.webm"}]'::jsonb, '2026-09-23T12:00:00Z', array['Musik', 'Klassik']::text[], 'q-v-orchester', 'ai_checked', 'published', 10, null, null, 'CC BY 3.0, University of Colorado Boulder College of Music – bearbeitet (Ausschnitt, Hochformat)', '{"en":{"title":"How an orchestra is organised","hook":"A symphony orchestra has four sections: strings, woodwind, brass and percussion.","description":"The University of Colorado Boulder Symphony Orchestra plays Beethoven''s Fifth Symphony. The strings sit at the front, the wind players behind them, percussion at the very back.","captions":["A symphony orchestra at work.","Strings at the front, wind players behind.","The conductor holds everyone together."]}}'::jsonb),
  ('v-vulkan', 'earth', 'Blick in einen Vulkankrater', 'Lava ist rund 1.000 Grad heiß. Solange das geschmolzene Gestein unter der Erde ist, heißt es Magma.', 'Ausbruch am Litli-Hrútur in Island, 2023. Island liegt auf der Grenze zweier Erdplatten, die auseinanderdriften – deshalb gibt es dort so viele Vulkane.', '/clips/v-vulkan.mp4', '/clips/v-vulkan.jpg', 8, false, '["Island, 2023: ein Vulkan bricht aus.","Die Lava ist rund 1.000 Grad heiß.","Unter der Erde heißt sie Magma."]'::jsonb, 'Giles Laurent', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:007_Volcano_eruption_of_Litli-Hr%C3%BAtur_in_Iceland_in_2023_Video_by_Giles_Laurent.webm"}]'::jsonb, '2026-09-22T12:00:00Z', array['Vulkane', 'Geologie']::text[], 'q-v-vulkan', 'ai_checked', 'published', 10, null, null, 'CC BY-SA 4.0, Giles Laurent – bearbeitet (Ausschnitt, Hochformat)', '{"en":{"title":"Looking into a volcanic crater","hook":"Lava is about 1,000 degrees hot. As long as the molten rock is underground, it is called magma.","description":"Eruption at Litli-Hrútur in Iceland, 2023. Iceland lies on the boundary of two tectonic plates that are drifting apart – which is why it has so many volcanoes.","captions":["Iceland, 2023: a volcano erupts.","The lava is about 1,000 degrees hot.","Underground it is called magma."]}}'::jsonb),
  ('v-gepard', 'earth', 'Das schnellste Landtier', 'Ein Gepard beschleunigt in etwa drei Sekunden auf fast 100 km/h.', 'Zeitlupenaufnahme eines sprintenden Gepards. Die biegsame Wirbelsäule wirkt wie eine Feder, der lange Schwanz hält das Tier in der Kurve im Gleichgewicht.', '/clips/v-gepard.mp4', '/clips/v-gepard.jpg', 8, false, '["Ein Gepard im Sprint, stark verlangsamt.","In drei Sekunden auf fast 100 km/h.","Der Schwanz hilft beim Steuern."]'::jsonb, 'Gregory Wilson', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:Cheetahs_on_the_Edge_(Director%27s_Cut).webm"}]'::jsonb, '2026-10-12T12:00:00Z', array['Tiere', 'Rekorde']::text[], 'q-v-gepard', 'ai_checked', 'published', 6, null, null, 'CC BY 3.0, Gregory Wilson – bearbeitet (Ausschnitt, Hochformat)', '{"en":{"title":"The fastest land animal","hook":"A cheetah accelerates to almost 100 km/h in about three seconds.","description":"Slow-motion footage of a sprinting cheetah. The flexible spine works like a spring, and the long tail keeps the animal balanced in turns.","captions":["A cheetah sprinting, greatly slowed down.","To almost 100 km/h in three seconds.","The tail helps with steering."]}}'::jsonb),
  ('v-oktopus', 'earth', 'Drei Herzen, blaues Blut', 'Ein Oktopus hat drei Herzen, blaues Blut und acht Arme, die teilweise selbstständig handeln.', 'Zwei Drittel der Nervenzellen eines Oktopus sitzen in den Armen. Sein Blut ist blau, weil es Sauerstoff mit Kupfer statt mit Eisen transportiert.', '/clips/v-oktopus.mp4', '/clips/v-oktopus.jpg', 9, false, '["Ein Oktopus im Aquarium.","Er hat drei Herzen und blaues Blut.","Seine Arme denken ein Stück weit mit."]'::jsonb, 'MartinThoma', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:Sealife-Munich-Octopus-2.ogv"}]'::jsonb, '2026-10-11T12:00:00Z', array['Tiere', 'Meer']::text[], 'q-v-oktopus', 'ai_checked', 'published', 6, null, null, 'CC0 (gemeinfrei)', '{"en":{"title":"Three hearts, blue blood","hook":"An octopus has three hearts, blue blood and eight arms that act partly on their own.","description":"Two thirds of an octopus''s nerve cells are in its arms. Its blood is blue because it carries oxygen with copper instead of iron.","captions":["An octopus in an aquarium.","It has three hearts and blue blood.","Its arms do some of the thinking."]}}'::jsonb),
  ('v-bienen', 'earth', 'Bienen sprechen im Tanz', 'Mit dem Schwänzeltanz zeigen Honigbienen ihren Schwestern, in welcher Richtung und wie weit entfernt Futter liegt.', 'Honigbienen auf der Wabe. Die Richtung des Tanzes zeigt den Winkel zur Sonne, die Dauer des Schwänzelns die Entfernung. Für diese Entdeckung erhielt Karl von Frisch 1973 den Nobelpreis.', '/clips/v-bienen.mp4', '/clips/v-bienen.jpg', 8, false, '["Honigbienen auf ihrer Wabe.","Mit einem Tanz zeigen sie den Weg zum Futter.","Richtung und Dauer verraten, wo es liegt."]'::jsonb, 'OakleyOriginals', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:Waggle_Dance.webm"}]'::jsonb, '2026-10-10T12:00:00Z', array['Tiere', 'Insekten']::text[], 'q-v-bienen', 'ai_checked', 'published', 10, null, null, 'CC BY 2.0, OakleyOriginals – bearbeitet (Ausschnitt, Hochformat)', '{"en":{"title":"Bees talk by dancing","hook":"With the waggle dance, honeybees show their sisters in which direction and how far away food is.","description":"Honeybees on the comb. The direction of the dance gives the angle to the Sun, the length of the waggle the distance. Karl von Frisch received the Nobel Prize in 1973 for this discovery.","captions":["Honeybees on their comb.","A dance shows the way to food.","Direction and duration reveal where it is."]}}'::jsonb),
  ('v-stare', 'earth', 'Tausend Vögel, eine Bewegung', 'In einem Starenschwarm achtet jeder Vogel nur auf seine nächsten Nachbarn – daraus entsteht die gemeinsame Bewegung.', 'Stare sammeln sich abends zu riesigen Schwärmen. Niemand führt den Schwarm an. Die dichten, wogenden Formen machen es Greifvögeln schwer, ein einzelnes Tier zu fassen.', '/clips/v-stare.mp4', '/clips/v-stare.jpg', 9, false, '["Stare sammeln sich in der Abenddämmerung.","Niemand führt den Schwarm an.","Jeder Vogel achtet nur auf seine Nachbarn."]'::jsonb, 'Karen Roe', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:Flock_of_starlings_(Sturnus_vulgaris).webm"}]'::jsonb, '2026-10-09T12:00:00Z', array['Tiere', 'Vögel']::text[], 'q-v-stare', 'ai_checked', 'published', 10, null, null, 'CC BY 2.0, Karen Roe – bearbeitet (Ausschnitt, Hochformat)', '{"en":{"title":"A thousand birds, one movement","hook":"In a flock of starlings each bird watches only its nearest neighbours – that is what creates the shared movement.","description":"Starlings gather in huge flocks in the evening. Nobody leads the flock. The dense, swirling shapes make it hard for birds of prey to pick out a single animal.","captions":["Starlings gather at dusk.","Nobody leads the flock.","Each bird watches only its neighbours."]}}'::jsonb),
  ('v-banknoten', 'economy', 'So entsteht ein 20-Euro-Schein', 'Euro-Banknoten bestehen nicht aus Papier, sondern aus reiner Baumwollfaser.', 'Druck der 20-Euro-Note. Baumwolle macht die Scheine reißfest und gibt ihnen ihren typischen Griff. Wasserzeichen, Hologramm und Sicherheitsfaden erschweren Fälschungen.', '/clips/v-banknoten.mp4', '/clips/v-banknoten.jpg', 8, false, '["Hier werden 20-Euro-Scheine gedruckt.","Sie bestehen aus Baumwolle, nicht aus Papier.","Viele Merkmale schützen vor Fälschung."]'::jsonb, 'Europäische Zentralbank', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:New_20_Euro_Banknotes_Printing_Production.webm"}]'::jsonb, '2026-10-08T12:00:00Z', array['Geld', 'Euro']::text[], 'q-v-banknoten', 'ai_checked', 'published', 10, null, null, 'CC BY 3.0, Europäische Zentralbank – bearbeitet (Ausschnitt, Hochformat)', '{"en":{"title":"How a 20-euro note is made","hook":"Euro banknotes are not made of paper but of pure cotton fibre.","description":"Printing the 20-euro note. Cotton makes the notes tear-resistant and gives them their typical feel. Watermark, hologram and security thread make counterfeiting harder.","captions":["This is where 20-euro notes are printed.","They are made of cotton, not paper.","Many features protect against forgery."]}}'::jsonb),
  ('v-muenzen', 'economy', 'Wie Münzen entstehen', 'Münzen werden geprägt: Stempel pressen das Motiv mit vielen Tonnen Druck in einen Metallrohling.', 'Frisch geprägte Quarter-Dollar-Münzen in der US-Münzanstalt West Point. Moderne Prägemaschinen schaffen mehrere Hundert Münzen pro Minute.', '/clips/v-muenzen.mp4', '/clips/v-muenzen.jpg', 6, false, '["Frisch geprägte Münzen in den USA.","Ein Stempel presst das Motiv ins Metall.","Hunderte Münzen pro Minute."]'::jsonb, 'United States Mint', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:West_Point_Quarters_B-Roll.webm"}]'::jsonb, '2026-10-07T12:00:00Z', array['Geld', 'Münzen']::text[], 'q-v-muenzen', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"How coins are made","hook":"Coins are minted: dies press the design into a metal blank with many tonnes of pressure.","description":"Freshly minted quarter-dollar coins at the US Mint in West Point. Modern coining presses produce several hundred coins a minute.","captions":["Freshly minted coins in the USA.","A die presses the design into the metal.","Hundreds of coins a minute."]}}'::jsonb),
  ('v-container', 'economy', 'Die Kiste, die den Welthandel veränderte', 'Rund 80 Prozent des Welthandels reisen per Schiff – der größte Teil der Stückgüter in genormten Containern.', 'Zeitraffer in einem Containerterminal in Gdynia, Polen. Weil Container weltweit dieselben Maße haben, passen sie auf Schiffe, Züge und Lastwagen – das Umladen dauert Minuten statt Tage.', '/clips/v-container.mp4', '/clips/v-container.jpg', 10, false, '["Ein Containerhafen im Zeitraffer.","Alle Container haben weltweit dieselben Maße.","So wurde Transport schnell und billig."]'::jsonb, 'PaSt Photo', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:MSC_Paris_-_berthing_at_BCT_Gdynia,_Timelapse..webm"}]'::jsonb, '2026-10-06T12:00:00Z', array['Handel', 'Logistik']::text[], 'q-v-container', 'ai_checked', 'published', 10, null, null, 'CC BY 3.0, PaSt Photo – bearbeitet (Ausschnitt, Hochformat)', '{"en":{"title":"The box that changed world trade","hook":"About 80 percent of world trade travels by ship – most general cargo in standardised containers.","description":"Time-lapse at a container terminal in Gdynia, Poland. Because containers have the same dimensions worldwide, they fit on ships, trains and lorries – transferring them takes minutes instead of days.","captions":["A container port in time-lapse.","All containers have the same dimensions worldwide.","That made transport fast and cheap."]}}'::jsonb),
  ('v-fliessband', 'business', 'Die Idee, die Autos bezahlbar machte', 'Henry Fords Fließband senkte die Bauzeit eines Autos von über zwölf Stunden auf rund anderthalb.', 'Aufnahmen aus einem Ford-Werk, um 1924. Jeder Arbeiter führte nur wenige Handgriffe aus, das Werkstück kam zu ihm. So sank der Preis des Model T von 850 auf unter 300 Dollar.', '/clips/v-fliessband.mp4', '/clips/v-fliessband.jpg', 8, false, '["Ein Ford-Werk in den 1920er-Jahren.","Jeder macht nur wenige Handgriffe.","So wurden Autos für viele bezahlbar."]'::jsonb, 'Ford Motor Company', 'footage', '[{"name":"Wikimedia Commons","url":"https://commons.wikimedia.org/wiki/File:Model_T_assembling_circa_1924.webm"}]'::jsonb, '2026-10-05T12:00:00Z', array['Industrie', 'Unternehmen']::text[], 'q-v-fliessband', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"The idea that made cars affordable","hook":"Henry Ford''s assembly line cut the time to build a car from more than twelve hours to about an hour and a half.","description":"Footage from a Ford plant, around 1924. Each worker performed only a few movements; the workpiece came to him. The price of the Model T fell from 850 to under 300 dollars.","captions":["A Ford plant in the 1920s.","Each worker does only a few movements.","That made cars affordable for many."]}}'::jsonb),
  ('v-supermarkt', 'business', 'Die Erfindung der Selbstbedienung', '1916 eröffnete in den USA der erste Laden, in dem Kunden die Ware selbst aus dem Regal nahmen.', 'Werbefilm eines kalifornischen Einkaufszentrums von 1957. Selbstbedienung senkte die Personalkosten und machte Verpackung und Marken wichtiger: Das Produkt musste sich nun selbst verkaufen.', '/clips/v-supermarkt.mp4', '/clips/v-supermarkt.jpg', 8, false, '["Ein Supermarkt in Kalifornien, 1957.","Kunden bedienen sich selbst.","Die Idee stammt aus dem Jahr 1916."]'::jsonb, 'Hillsdale Shopping Center', 'footage', '[{"name":"Internet Archive (Prelinger Archives)","url":"https://archive.org/details/Shopping1957"}]'::jsonb, '2026-10-04T12:00:00Z', array['Handel', 'Geschäftsmodell']::text[], 'q-v-supermarkt', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"The invention of self-service","hook":"In 1916 the first shop opened in the USA where customers took goods from the shelves themselves.","description":"Promotional film for a Californian shopping centre from 1957. Self-service lowered staff costs and made packaging and brands more important: the product now had to sell itself.","captions":["A supermarket in California, 1957.","Customers serve themselves.","The idea dates from 1916."]}}'::jsonb),
  ('v-buero', 'business', 'Büroarbeit vor dem Computer', '1950 wurde jeder Brief und jede Rechnung auf der Schreibmaschine getippt – unsere Tastatur stammt aus dieser Welt.', 'Lehrfilm „Office Etiquette“ von 1950. Die Tastenanordnung QWERTY wurde in den 1870er-Jahren für Schreibmaschinen entwickelt und ist bis heute Standard, im Deutschen als QWERTZ.', '/clips/v-buero.mp4', '/clips/v-buero.jpg', 5, false, '["Ein Büro im Jahr 1950.","Jeder Brief entsteht auf der Schreibmaschine.","Ihre Tastatur nutzen wir noch heute."]'::jsonb, 'Coronet Instructional Films', 'footage', '[{"name":"Internet Archive (Prelinger Archives)","url":"https://archive.org/details/OfficeEt1950"}]'::jsonb, '2026-10-03T12:00:00Z', array['Arbeit', 'Büro']::text[], 'q-v-buero', 'ai_checked', 'published', 10, null, null, 'Gemeinfrei', '{"en":{"title":"Office work before the computer","hook":"In 1950 every letter and invoice was typed on a typewriter – our keyboard comes from that world.","description":"Educational film “Office Etiquette” from 1950. The QWERTY layout was developed for typewriters in the 1870s and is still the standard today.","captions":["An office in 1950.","Every letter is written on a typewriter.","We still use its keyboard today."]}}'::jsonb)
